  }
  .duoop-chart__emblem {
    width: 44px;
    height: 44px;
  }
  .duoop-chart__footer {
    padding: 16px;
  }
  .duoop-chart__data summary {
    min-height: 32px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-chart[data-animate='true'] .duoop-chart__marks {
    animation: none;
  }
  .duoop-chart__legend button {
    transition: none;
  }
}

