.duoop-button {
  --button-face: #373434;
  --button-text: #fff;
  --button-edge: #1d1b1b;
  --button-depth: 4px;
  appearance: none;
  display: inline-grid;
  place-items: center;
  position: relative;
  min-height: 44px;
  max-width: 100%;
  padding: 10px 20px;
  border: 2px solid var(--button-edge);
  border-radius: 10px;
  background: var(--button-face);
  color: var(--button-text);
  box-shadow: 0 var(--button-depth) 0 var(--button-edge);
  font: inherit;
  font-size: 14px;
  font-weight: 650;
  line-height: 1.4;
  text-align: center;
  text-decoration: none;
  overflow-wrap: anywhere;
  cursor: pointer;
  touch-action: manipulation;
  transition:
    transform 100ms ease,
    box-shadow 100ms ease,
    background-color 100ms ease;
}
.duoop-button--outline {
  --button-face: #fff;
  --button-text: #191919;
  --button-edge: #191919;
}
.duoop-button--ghost {
  --button-face: transparent;
  --button-text: #191919;
  --button-edge: transparent;
  --button-depth: 0px;
}
.duoop-button--sm {
  --button-depth: 3px;
  padding: 8px 14px;
  font-size: 12px;
}
.duoop-button--lg {
  --button-depth: 5px;
  min-height: 52px;
  padding: 12px 26px;
  font-size: 16px;
}
.duoop-button--ghost {
  --button-depth: 0px;
}

.duoop-button--icon {
  width: 44px;
  padding-inline: 10px;
}
.duoop-button--icon.duoop-button--lg {
  width: 52px;
}
.duoop-button--full {
  width: 100%;
}
.duoop-button-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 0;
}
.duoop-button-content > span {
  min-width: 0;
}
.duoop-button-icon {
  display: inline-flex;
  flex: 0 0 auto;
}
.duoop-button-icon svg {
  width: 1.15em;
  height: 1.15em;
}
.duoop-button-status {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 20px;
  pointer-events: none;
}
.duoop-button[data-status]:not([data-status='idle']) .duoop-button-content {
  visibility: hidden;
}
.duoop-button[aria-pressed='true'] {
  --button-face: #dedede;
  --button-text: #111;
  --button-edge: #111;
  box-shadow: none;
  transform: translateY(var(--button-depth));
}
.duoop-button[data-intent='destructive'] .duoop-button-content {
  text-decoration: underline;
  text-underline-offset: 3px;
}
@media (hover: hover) {
  .duoop-button:hover:not([aria-disabled='true']) {
    background: #302e2e;
  }
  .duoop-button--outline:hover:not([aria-disabled='true']),
  .duoop-button--ghost:hover:not([aria-disabled='true']),
  .duoop-button[aria-pressed='true']:hover {
    background: #ededed;
  }
}
.duoop-button:active:not([aria-disabled='true']) {
  transform: translateY(var(--button-depth));
  box-shadow: none;
}
.duoop-button:focus-visible {
  outline: none;
}
.duoop-button:disabled,
.duoop-button[aria-disabled='true']:not([data-status='loading']):not(
    [data-status='success']
  ) {
  --button-face: #efefef;
  --button-text: #777;
  --button-edge: #ccc;
  opacity: 1;
  cursor: not-allowed;
}
.duoop-button[data-status='loading'] {
  cursor: progress;
}
.duoop-button[data-status='success'] {
  cursor: default;
}
.duoop-spinner {
  width: 17px;
  height: 17px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: duoop-spin 0.7s linear infinite;
}
.duoop-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
@keyframes duoop-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-button {
    transition: none;
  }
  .duoop-spinner {
    animation: none;
    border-style: solid;
  }
}

/* A shared mechanical response; intensity changes travel and spring. */
.duoop-button {
  --lift: -1px;
  --arrow-travel: 3px;
  --return-ease: cubic-bezier(0.2, 1.5, 0.4, 1);
  isolation: isolate;
  transition:
    transform 220ms var(--return-ease),
    box-shadow 220ms var(--return-ease),
    background-color 160ms ease,
    color 160ms ease;
}
.duoop-button[data-motion='discreet'] {
  --lift: 0px;
  --arrow-travel: 1px;
  --return-ease: ease-out;
}
.duoop-button[data-motion='expressive'] {
  --lift: -2px;
  --arrow-travel: 5px;
  --return-ease: cubic-bezier(0.2, 1.9, 0.4, 1);
}
.duoop-button-content,
.duoop-button-status,
.duoop-button-reserve {
  grid-area: 1 / 1;
}
.duoop-button-content {
  position: relative;
  z-index: 1;
  width: 100%;
}
.duoop-button-status {
  position: relative;
  inset: auto;
  z-index: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  font-size: inherit;
}
.duoop-button-reserve {
  display: grid;
  visibility: hidden;
  height: 0;
  pointer-events: none;
}
.duoop-button-reserve > span {
  grid-area: 1 / 1;
}
.duoop-button-icon {
  transition: transform 160ms ease;
}
@media (hover: hover) {
  .duoop-button:hover:not([aria-disabled='true']):not([aria-pressed='true']) {
    transform: translateY(var(--lift));
    box-shadow: 0 calc(var(--button-depth) - var(--lift)) 0 var(--button-edge);
  }
  .duoop-button:hover:not([aria-disabled='true']) [data-icon-motion='arrow'] {
    transform: translateX(var(--arrow-travel));
  }
}
.duoop-button:active:not([aria-disabled='true']) {
  transform: translateY(var(--button-depth)) !important;
  box-shadow: none !important;
  transition-duration: 80ms;
  transition-timing-function: ease-out;
}
.duoop-button[aria-pressed='true'] {
  transform: translateY(var(--button-depth));
  box-shadow: none;
}
.duoop-button--ghost:hover:not([aria-disabled='true']) {
  box-shadow: none;
}
.duoop-check {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  animation: duoop-confirm 280ms ease-out;
}
.duoop-check path {
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
  animation: duoop-draw 240ms ease-out;
}
.duoop-button[data-status='error'] .duoop-button-status {
  animation: duoop-error 240ms ease-out;
}
.duoop-button [data-icon-motion='plus'][data-activated='true'] {
  animation: duoop-add 240ms ease-out;
}
.duoop-button[aria-pressed='true'] [data-icon-motion='star'] {
  animation: duoop-confirm 280ms ease-out;
}
.duoop-button[data-motion='discreet'] .duoop-check,
.duoop-button[data-motion='discreet'] .duoop-button-status,
.duoop-button[data-motion='discreet'] .duoop-button-icon {
  animation: none;
}
@keyframes duoop-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes duoop-confirm {
  0% {
    transform: scale(0.85);
  }
  60% {
    transform: scale(1.12);
  }
  100% {
    transform: scale(1);
  }
}
@keyframes duoop-error {
  25% {
    transform: translateX(-2px);
  }
  65% {
    transform: translateX(2px);
  }
  100% {
    transform: translateX(0);
  }
}
@keyframes duoop-add {
  to {
    transform: rotate(90deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-button,
  .duoop-button *,
  .duoop-button::before {
    transition: none !important;
    animation: none !important;
  }
  .duoop-button:hover:not([aria-disabled='true']):not([aria-pressed='true']) {
    transform: none;
    box-shadow: 0 var(--button-depth) 0 var(--button-edge);
  }
  .duoop-button:hover [data-icon-motion='arrow'] {
    transform: none;
  }
}
.duoop-button[data-motion='discreet'] .favorite-star {
  animation: none;
}

/* Intent variants share the same mechanical geometry. */
.duoop-button--destructive {
  --button-face: #b42332;
  --button-text: #fff;
  --button-edge: #681322;
}
.duoop-button--destructive-outline {
  --button-face: #fff;
  --button-text: #a51d2d;
  --button-edge: #a51d2d;
}
.duoop-button--destructive[aria-pressed='true'] {
  --button-face: #801b29;
  --button-text: #fff;
  --button-edge: #681322;
}
.duoop-button--destructive-outline[aria-pressed='true'] {
  --button-face: #ffe9ec;
  --button-text: #8a1927;
  --button-edge: #a51d2d;
}
.duoop-button--link {
  --button-face: transparent;
  --button-text: #191919;
  --button-edge: transparent;
  --button-depth: 0px;
  padding-inline: 8px;
  border-radius: 4px;
}
.duoop-button--link .duoop-button-label {
  text-decoration: underline;
  text-decoration-color: #b8b8b8;
  text-underline-offset: 5px;
  text-decoration-thickness: 1px;
  position: relative;
}
.duoop-button--link .duoop-button-label::after {
  content: '';
  position: absolute;
  inset: auto 0 -3px;
  height: 2px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 160ms ease-out;
  pointer-events: none;
}
.duoop-button--link[aria-pressed='true'] {
  --button-face: #efefef;
  --button-edge: transparent;
}
.duoop-button--link:focus-visible .duoop-button-label::after {
  transform: scaleX(1);
}
@media (hover: hover) {
  .duoop-button--destructive:hover:not([aria-disabled='true']) {
    background: #981f2d;
  }
  .duoop-button--destructive-outline:hover:not([aria-disabled='true']) {
    background: #fff0f2;
  }
  .duoop-button--link:hover:not([aria-disabled='true']):not([aria-pressed='true']) {
    background: transparent;
    transform: none;
    box-shadow: none;
  }
  .duoop-button--link:hover:not([aria-disabled='true']) .duoop-button-label::after {
    transform: scaleX(1);
  }
}
.duoop-button--link:disabled,
.duoop-button--link[aria-disabled='true'] {
  --button-depth: 0px;
  --button-edge: transparent;
}
@media (prefers-reduced-motion: reduce) {
  .duoop-button--link .duoop-button-label::after {
    transition: none;
  }
}
/* Custom palettes retain the semantics of filled, outlined and text variants. */
.duoop-button[data-custom-color] {
  --button-face: var(--custom-face);
  --button-text: var(--custom-text);
  --button-edge: var(--custom-edge);
}
.duoop-button[data-custom-color]:is(
    .duoop-button--outline,
    .duoop-button--destructive-outline
  ) {
  --button-face: #fff;
  --button-text: var(--custom-ink);
  --button-edge: var(--custom-ink);
}
.duoop-button[data-custom-color]:is(.duoop-button--ghost, .duoop-button--link) {
  --button-face: transparent;
  --button-text: var(--custom-ink);
  --button-edge: transparent;
}
.duoop-button[data-custom-color][aria-pressed='true'] {
  --button-face: var(--custom-hover);
}
.duoop-button[data-custom-color][aria-pressed='true']:is(
    .duoop-button--outline,
    .duoop-button--destructive-outline,
    .duoop-button--ghost,
    .duoop-button--link
  ) {
  --button-face: var(--custom-tint);
}
@media (hover: hover) {
  .duoop-button[data-custom-color]:hover:not([aria-disabled='true']) {
    background: var(--custom-hover);
  }
  .duoop-button[data-custom-color]:is(
      .duoop-button--outline,
      .duoop-button--destructive-outline,
      .duoop-button--ghost,
      .duoop-button--link
    ):hover:not([aria-disabled='true']) {
    background: var(--custom-tint);
  }
}
.duoop-button[data-custom-color]:disabled,
.duoop-button[data-custom-color][aria-disabled='true']:not(
    [data-status='loading']
  ):not([data-status='success']) {
  --button-face: #efefef;
  --button-text: #777;
  --button-edge: #ccc;
}

/* Outcomes share one visual rhythm: reveal, traced ring, then check. */
.action-feedback {
  --feedback-ink: #356247;
  --feedback-soft: #edf5ef;
  font-size: 12px;
  line-height: 1.6;
}
.action-feedback[data-tone='error'] {
  --feedback-ink: #a51d2d;
  --feedback-soft: #fff2f3;
}
.action-feedback-content {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 10px;
  background: var(--feedback-soft);
  color: var(--feedback-ink);
  animation: feedback-reveal 280ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.action-feedback-content svg {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.feedback-orbit {
  stroke-dasharray: 1;
  animation: feedback-trace 360ms ease-out both;
  transform: rotate(-90deg);
  transform-origin: center;
}
.feedback-symbol {
  stroke-dasharray: 1;
  animation: feedback-trace 240ms 160ms ease-out both;
}
@keyframes feedback-trace {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes feedback-reveal {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.duoop-button[data-status='success'] {
  --button-face: #356247;
  --button-edge: #234631;
  --button-text: #fff;
  background: var(--button-face);
  color: var(--button-text);
  animation: feedback-reveal 240ms ease-out;
}
.duoop-button[data-status='error'] {
  --button-face: #a51d2d;
  --button-edge: #761725;
  --button-text: #fff;
  background: var(--button-face);
  color: var(--button-text);
}
.duoop-button:focus-visible {
  outline: none;
}
.duoop-button:focus-visible::after {
  content: '';
  position: absolute;
  inset: auto 5px 4px;
  height: 2px;
  background: currentColor;
  border-radius: 1px;
  pointer-events: none;
}
@media (prefers-reduced-motion: reduce) {
  .action-feedback-content,
  .feedback-orbit,
  .feedback-symbol,
  .duoop-button[data-status='success'] {
    animation: none;
  }
}

.action-feedback:empty {
  display: none;
}

