.duoop-checkbox,
.duoop-checkbox-group,
.checkbox-surface {
  --check-fg: #373434;
  --check-muted: #686565;
  --check-bg: #fff;
  --check-border: #777474;
  --check-soft: #f0eeee;
  --check-error: #a51d2d;
  --check-shadow: #1d1b1b;
  color: var(--check-fg);
  min-width: 0;
}
.checkbox-surface[data-theme='dark'] {
  --check-fg: #f3eeee;
  --check-muted: #bdb5b5;
  --check-bg: #252323;
  --check-border: #b0a6a6;
  --check-soft: #383333;
  --check-error: #ff9dab;
  --check-shadow: #111;
  background: var(--check-bg);
  color: var(--check-fg);
  color-scheme: dark;
}

/* Theme tokens inherit through each primitive, including nested groups. */
.checkbox-surface[data-theme='dark'] :is(.duoop-checkbox, .duoop-checkbox-group) {
  --check-fg: #f3eeee;
  --check-muted: #bdb5b5;
  --check-bg: #252323;
  --check-border: #b0a6a6;
  --check-soft: #383333;
  --check-error: #ff9dab;
  --check-shadow: #111;
}
.duoop-checkbox {
  --check-size: 20px;
  font-size: 13px;
  line-height: 1.5;
}
.duoop-checkbox--sm {
  --check-size: 16px;
  font-size: 12px;
}
.duoop-checkbox--lg {
  --check-size: 24px;
  font-size: 15px;
}
.checkbox-label {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  min-height: 44px;
  padding-block: 11px;
  cursor: pointer;
  margin: 0;
  font: inherit;
}
.checkbox-control {
  position: relative;
  flex: 0 0 var(--check-size);
  width: var(--check-size);
  height: var(--check-size);
  margin-block: 1px;
}
.checkbox-control input {
  position: absolute;
  inset: 0;
  opacity: 0;
  width: 100%;
  height: 100%;
  min-height: 0;
  padding: 0;
  margin: 0;
  cursor: inherit;
  z-index: 1;
}
.checkbox-box {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--check-bg);
  border: 2px solid var(--check-border);
  border-radius: 5px;
  box-shadow: 0 2px 0 var(--check-border);
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    transform 140ms ease,
    box-shadow 140ms ease;
}
.checkbox-box svg {
  width: 100%;
  height: 100%;
  stroke: var(--check-bg);
  stroke-width: 2.3;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.checkbox-tick {
  stroke-dasharray: 18;
  stroke-dashoffset: 18;
  opacity: 0;
  transition:
    stroke-dashoffset 160ms ease-out,
    opacity 100ms ease;
}
.checkbox-dash {
  opacity: 0;
  transform: scaleX(0.4);
  transform-origin: center;
  transition:
    transform 140ms ease,
    opacity 100ms ease;
}
.checkbox-control input:checked + .checkbox-box,
.checkbox-control input:indeterminate + .checkbox-box {
  background: var(--check-fg);
  border-color: var(--check-fg);
  box-shadow: 0 2px 0 var(--check-shadow);
}
.checkbox-control input:checked:not(:indeterminate) + .checkbox-box .checkbox-tick {
  stroke-dashoffset: 0;
  opacity: 1;
}
.checkbox-control input:indeterminate + .checkbox-box .checkbox-dash {
  opacity: 1;
  transform: scaleX(1);
}
.checkbox-label:hover .checkbox-control input:not(:disabled) + .checkbox-box {
  border-color: var(--check-fg);
}
.checkbox-label:active
  .checkbox-control
  input:not(:disabled):not([readonly])
  + .checkbox-box {
  transform: translateY(2px);
  box-shadow: 0 0 0 var(--check-shadow);
}
.checkbox-control input:focus-visible + .checkbox-box {
  outline: none;
  border-style: dashed;
}
.checkbox-content {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 5px;
}
.checkbox-title {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px 7px;
  font-weight: 550;
  overflow-wrap: anywhere;
}
.checkbox-title small {
  color: var(--check-muted);
  font-size: 11px;
  font-weight: 400;
}
.checkbox-description {
  color: var(--check-muted);
  font-size: 12px;
  line-height: 1.65;
  overflow-wrap: anywhere;
}
.checkbox-badge {
  border: 1px solid var(--check-border);
  border-radius: 5px;
  padding: 0 6px;
  font-size: 10px;
  font-weight: 500;
}
.checkbox-icon {
  line-height: 1;
}
.duoop-checkbox[data-position='after'] .checkbox-control {
  order: 2;
}
.duoop-checkbox--row .checkbox-label,
.duoop-checkbox--card .checkbox-label {
  padding: 16px;
  border: 2px solid var(--check-border);
  border-radius: 10px;
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    box-shadow 140ms ease;
}
.duoop-checkbox--row .checkbox-label {
  padding: 12px;
  border-color: transparent;
}
.duoop-checkbox--card .checkbox-label:has(input:checked),
.duoop-checkbox--card .checkbox-label:has(input:indeterminate) {
  background: var(--check-soft);
  border-color: var(--check-fg);
  box-shadow: 0 3px 0 var(--check-shadow);
}
.duoop-checkbox--row .checkbox-label:hover:not(:has(input:disabled)),
.duoop-checkbox--card .checkbox-label:hover:not(:has(input:disabled)) {
  background: var(--check-soft);
}
.checkbox-label:has(input:disabled) {
  opacity: 0.5;
  cursor: not-allowed;
}
.duoop-checkbox[data-readonly] .checkbox-label {
  cursor: default;
}
.checkbox-control input[aria-invalid='true'] + .checkbox-box {
  border-color: var(--check-error);
  box-shadow: 0 2px 0 var(--check-error);
}
.duoop-checkbox--card .checkbox-label:has(input[aria-invalid='true']) {
  border-color: var(--check-error);
  box-shadow: 0 3px 0 var(--check-error);
}
.checkbox-error {
  margin: 8px 0 0;
  color: var(--check-error);
  font-size: 12px;
  line-height: 1.6;
}
.duoop-checkbox-group {
  width: 100%;
  padding: 0;
  margin: 0;
  border: 0;
}
.duoop-checkbox-group legend {
  font-size: 13px;
  font-weight: 600;
  padding: 0;
  margin-bottom: 12px;
}
.checkbox-group-description {
  color: var(--check-muted);
  font-size: 12px;
  line-height: 1.6;
  margin: 0 0 12px;
}
.checkbox-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.checkbox-options--horizontal {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px 20px;
}
.checkbox-options--grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
  gap: 12px;
}
.checkbox-children {
  padding-inline-start: 22px;
  margin-inline-start: 9px;
  border-inline-start: 1px solid var(--check-border);
}
.checkbox-illustration {
  display: grid;
  place-items: center;
  height: 65px;
  border-radius: 6px;
  background: var(--check-soft);
}
.checkbox-illustration svg {
  width: 48px;
  height: 48px;
  stroke: currentColor;
}
@media (prefers-reduced-motion: reduce) {
  .checkbox-box,
  .checkbox-tick,
  .checkbox-dash,
  .duoop-checkbox--row .checkbox-label,
  .duoop-checkbox--card .checkbox-label {
    transition: none;
  }
}
@media (forced-colors: active) {
  .checkbox-box {
    forced-color-adjust: none;
    background: Canvas;
    border-color: ButtonText;
  }
  .checkbox-control input:checked + .checkbox-box,
  .checkbox-control input:indeterminate + .checkbox-box {
    background: Highlight;
    border-color: Highlight;
  }
  .checkbox-box svg {
    stroke: HighlightText;
  }
}

/* Invalid is a complete palette, never a red edge around a neutral fill. */
.duoop-checkbox:has(input[aria-invalid='true']) {
  --check-fg: var(--check-error);
  --check-border: var(--check-error);
  --check-shadow: var(--check-error);
  --check-soft: #fff2f3;
  --check-muted: #945663;
}
.checkbox-surface[data-theme='dark']
  .duoop-checkbox:has(input[aria-invalid='true']) {
  --check-fg: var(--check-error);
  --check-border: var(--check-error);
  --check-shadow: #ad6070;
  --check-soft: #3b282d;
  --check-muted: #dfadba;
}
.checkbox-control input:focus {
  outline: none;
}
.checkbox-error {
  animation: checkbox-feedback 220ms ease-out;
}
@keyframes checkbox-feedback {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* An illustrated option reads as a document cover, with the control in its header. */
.duoop-checkbox:has(.checkbox-illustration) .checkbox-label {
  position: relative;
  padding: 22px;
}
.duoop-checkbox:has(.checkbox-illustration) .checkbox-control {
  position: absolute;
  inset-block-start: 20px;
  inset-inline-end: 20px;
}
.checkbox-illustration {
  height: 138px;
  margin: -6px -6px 12px;
  background: transparent;
}
.checkbox-illustration svg {
  width: 156px;
  height: 118px;
  overflow: visible;
}
.brief-sheet {
  fill: var(--check-bg);
  stroke: var(--check-border);
  transition: transform 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
  transform-origin: center;
}
.brief-sheet--back {
  fill: var(--check-soft);
  transform: rotate(-9deg) translate(-8px, 2px);
}
.checkbox-label:hover .brief-sheet--back {
  transform: rotate(-14deg) translate(-12px, 0);
}
.checkbox-label:has(input:checked) .brief-sheet--front {
  transform: translateY(-4px) rotate(3deg);
}
.brief-lines {
  stroke: var(--check-border);
}
@media (prefers-reduced-motion: reduce) {
  .checkbox-error {
    animation: none;
  }
  .brief-sheet {
    transition: none;
  }
}
@media (forced-colors: active) {
  .checkbox-control input:focus-visible + .checkbox-box {
    border: 3px solid Highlight;
  }
}

