/* The fill grows inside the fixed outline; the button keeps its geometry. */
.favorite-star {
  overflow: visible;
  transform-origin: center;
}
.favorite-star-fill {
  transform: scale(0);
  transform-origin: 12px 12px;
  opacity: 0;
  transition:
    transform 240ms ease-out,
    opacity 180ms ease-out;
}
.duoop-button[aria-pressed='true'] .favorite-star-fill {
  transform: scale(1);
  opacity: 1;
}
.duoop-button[aria-pressed='true'] .favorite-star {
  animation: favorite-pop 320ms ease-out;
}
@keyframes favorite-pop {
  0% {
    transform: scale(1);
  }
  45% {
    transform: scale(1.25) rotate(-8deg);
  }
  75% {
    transform: scale(0.95) rotate(3deg);
  }
  100% {
    transform: scale(1) rotate(0);
  }
}
