  .gallery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 650px) {
  .gallery-grid {
    grid-template-columns: 1fr;
  }
  .gallery-toolbar,
  .gallery-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }
  .gallery-toolbar {
    margin: 20px 0;
  }
  .example-dialog {
    padding: 18px;
  }
}
.color-control {
  grid-column: 1 / -1;
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}
.color-control legend {
  font-size: 11px;
  color: #555d69;
  padding: 0;
  margin-bottom: 8px;
}
.color-inputs {
  display: flex;
  align-items: center;
  gap: 10px;
}
.button-controls .color-inputs input[type='color'] {
  width: 44px;
  height: 40px;
  padding: 3px;
  margin: 0;
  flex-shrink: 0;
  cursor: pointer;
}
.button-controls .color-inputs input:not([type='color']) {
  width: 120px;
  margin: 0;
  font-family: monospace;
}
.color-inputs button {
  border: 1px solid var(--border);
  background: #fff;
  padding: 8px 12px;
  min-height: 40px;
}
.color-control p {
  font-size: 11px;
  line-height: 1.5;
  color: var(--muted);
  margin: 8px 0 0;
}

.gallery-groups {
  display: flex;
  flex-direction: column;
  gap: 52px;
}
.gallery-category {
  min-width: 0;
  scroll-margin-top: 100px;
}
.gallery-category-heading {
  display: flex;
  align-items: baseline;
  gap: 16px;
  padding-bottom: 16px;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--border);
}
.gallery-category-heading h4 {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.3px;
}
.gallery-category-heading > span {
  color: var(--muted);
  font-size: 11px;
}
@media (max-width: 650px) {
  .gallery-groups {
    gap: 36px;
  }
  .gallery-category-heading {
    margin-bottom: 16px;
  }
}

