.duoop-dialog {
  inset: 0;
  margin: auto;
  width: max-content;
  height: max-content;
  max-width: none;
  max-height: none;
  padding: 0;
  border: 0;
  background: transparent;
  color: #373434;
  overflow: visible;
}
.duoop-dialog::backdrop {
  background: rgb(37 42 52 / 0.38);
  backdrop-filter: blur(3px);
  animation: dialog-backdrop 200ms ease-out;
}
.duoop-dialog[open] {
  animation: dialog-enter 250ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.duoop-dialog__surface {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(calc(100vw - 32px), 560px);
  max-height: min(calc(100dvh - 48px), 760px);
  border: 2px solid #373434;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 6px 0 #1d1b1b;
  overflow: hidden;
}
.duoop-dialog--sm .duoop-dialog__surface {
  width: min(calc(100vw - 32px), 420px);
}
.duoop-dialog--lg .duoop-dialog__surface {
  width: min(calc(100vw - 32px), 760px);
}
.duoop-dialog--xl .duoop-dialog__surface {
  width: min(calc(100vw - 32px), 980px);
}
.duoop-dialog--fullscreen .duoop-dialog__surface {
  width: calc(100vw - 32px);
  height: calc(100dvh - 32px);
  max-height: none;
}
.duoop-dialog__header {
  flex-shrink: 0;
  padding: 32px 76px 24px 32px;
  background: #f7f6f5;
  border-bottom: 2px solid #373434;
}
.duoop-dialog__header h2 {
  margin: 0 0 10px;
  font-size: 28px;
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.9px;
  text-wrap: balance;
}
.duoop-dialog__header p {
  margin: 0;
  color: #686565;
  font-size: 13px;
  line-height: 1.65;
  max-width: 48ch;
}
.duoop-dialog__body {
  padding: 28px 32px;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  font-size: 13px;
  line-height: 1.65;
}
.duoop-dialog__body > :first-child {
  margin-top: 0;
}
.duoop-dialog__body > :last-child {
  margin-bottom: 0;
}
.duoop-dialog__body > * + .action-feedback {
  margin-block-start: 20px;
}
.duoop-dialog__footer {
  flex-shrink: 0;
  padding: 20px 32px 24px;
  border-top: 1px solid #dedada;
  background: #faf9f8;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}
.duoop-dialog__footer[data-bare] {
  border: 0;
  background: #fff;
  padding-top: 0;
}
.duoop-dialog__close {
  position: absolute;
  z-index: 1;
  inset-block-start: 24px;
  inset-inline-end: 24px;
  width: 44px;
  height: 44px;
  color: inherit;
  border: 2px solid #373434;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 0 #1d1b1b;
  display: grid;
  place-items: center;
  cursor: pointer;
  transition:
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 180ms ease,
    background 150ms ease;
}
.duoop-dialog__close:hover {
  background: #f0eeee;
  transform: translateY(-2px);
  box-shadow: 0 5px 0 #1d1b1b;
}
.duoop-dialog__close:active {
  transform: translateY(3px);
  box-shadow: 0 0 0 #1d1b1b;
}
.duoop-dialog__close:focus-visible {
  outline: none;
}
.duoop-dialog__close svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}
.duoop-dialog__body input,
.duoop-dialog__body textarea {
  box-sizing: border-box;
  width: 100%;
  min-height: 46px;
  margin-top: 8px;
  border: 2px solid #777474;
  border-radius: 10px;
  padding: 12px 14px;
  background: #fff;
  color: #373434;
  font: inherit;
  font-weight: 400;
  transition:
    border-color 150ms ease,
    background 150ms ease;
}
.duoop-dialog__body input:focus,
.duoop-dialog__body textarea:focus {
  outline: none;
  border-color: #373434;
  background: #faf9f8;
  box-shadow: inset 3px 0 #373434;
}
.duoop-dialog__body [aria-invalid='true'] {
  border-color: #a51d2d;
  background: #fff2f3;
  color: #a51d2d;
}
.duoop-dialog__body label {
  display: block;
  font-weight: 600;
}
.duoop-dialog__body label + label {
  margin-top: 20px;
}
.duoop-dialog__body textarea {
  resize: vertical;
}
.dialog-demo-eyebrow {
  display: block;
  margin-bottom: 16px;
  color: #686565;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1.6px;
  text-transform: uppercase;
}
.dialog-demo-project {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 24px;
}
.dialog-demo-project svg {
  width: 48px;
  height: 56px;
  flex-shrink: 0;
  fill: #f0eeee;
  stroke: #373434;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.dialog-demo-project strong {
  display: block;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.4px;
}
.dialog-demo-project span {
  display: block;
  margin-block-start: 5px;
  color: #686565;
  font-size: 12px;
}
.dialog-demo-details {
  margin: 0;
  border-block: 1px solid #dedada;
}
.dialog-demo-details > div {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 13px 0;
}
.dialog-demo-details > div + div {
  border-top: 1px solid #e9e6e4;
}
.dialog-demo-details dt {
  color: #686565;
}
.dialog-demo-details dd {
  margin: 0;
  font-weight: 550;
  text-align: end;
}
.dialog-demo-note {
  margin: 20px 0 0;
  color: #686565;
  font-size: 12px;
}
.dialog-demo-note + .duoop-button {
  margin-block-start: 16px;
}
.dialog-demo-error {
  color: #a51d2d;
  margin: 8px 0 20px;
  font-size: 12px;
}
.dialog-demo-section {
  padding-block: 20px;
  border-bottom: 1px solid #dedada;
}
.dialog-demo-section h3 {
  font-size: 16px;
  margin: 0 0 8px;
}
.dialog-demo-section p {
  margin: 0;
  color: #686565;
}
@keyframes dialog-enter {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.975);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes dialog-backdrop {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (max-width: 600px) {
  .duoop-dialog--mobile-bottom {
    inset: auto 0 0;
    margin: 0;
    width: 100%;
  }
  .duoop-dialog--mobile-bottom .duoop-dialog__surface {
    width: 100%;
    box-sizing: border-box;
    max-height: 88dvh;
    border-radius: 16px 16px 0 0;
    border-bottom: 0;
  }
  .duoop-dialog--mobile-fullscreen {
    margin: 0;
    width: 100%;
  }
  .duoop-dialog--mobile-fullscreen .duoop-dialog__surface {
    width: 100%;
    box-sizing: border-box;
    height: 100dvh;
    max-height: none;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
  .duoop-dialog__header {
    padding: 24px 72px 22px 20px;
  }
  .duoop-dialog__header h2 {
    font-size: 25px;
  }
  .duoop-dialog__close {
    inset-block-start: 20px;
    inset-inline-end: 18px;
  }
  .duoop-dialog__body {
    padding: 24px 20px;
  }
  .duoop-dialog__footer {
    padding: 18px 20px max(24px, env(safe-area-inset-bottom));
    flex-wrap: wrap;
  }
  .duoop-dialog__footer > .duoop-button {
    flex: 1;
  }
  .duoop-dialog__body input,
  .duoop-dialog__body textarea {
    font-size: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-dialog[open],
  .duoop-dialog::backdrop {
    animation: dialog-backdrop 120ms ease-out;
  }
  .duoop-dialog__close {
    transition: none;
  }
  .duoop-dialog__close:hover,
  .duoop-dialog__close:active {
    transform: none;
  }
}

