import { useLayoutEffect, useState } from 'react';

const VIEWPORT_GUTTER = 12;

export function useAnchoredOverlay({
  open,
  anchorRef,
  overlayRef,
  placement = 'bottom-start',
  gap = 8,
  minimumWidth = 0,
  matchAnchorWidth = false,
}) {
  const [position, setPosition] = useState({
    ready: false,
    left: 0,
    top: 0,
    resolvedPlacement: placement,
  });
  useLayoutEffect(() => {
    if (!open) return undefined;
    const anchor = anchorRef.current;
    const overlay = overlayRef.current;
    if (!anchor || !overlay) return undefined;
    function update() {
      const anchorRect = anchor.getBoundingClientRect();
      const width = matchAnchorWidth
        ? anchorRect.width
        : Math.max(overlay.offsetWidth, minimumWidth, anchorRect.width);
      const height = overlay.offsetHeight;
      const [preferredSide, alignment = 'start'] = placement.split('-');
      const roomBelow = window.innerHeight - anchorRect.bottom - VIEWPORT_GUTTER;
      const roomAbove = anchorRect.top - VIEWPORT_GUTTER;
      const roomRight = window.innerWidth - anchorRect.right - VIEWPORT_GUTTER;
      const roomLeft = anchorRect.left - VIEWPORT_GUTTER;
      let side = preferredSide;
      if (side === 'bottom' && height > roomBelow && roomAbove > roomBelow)
        side = 'top';
      if (side === 'top' && height > roomAbove && roomBelow > roomAbove)
        side = 'bottom';
      if (side === 'right' && width > roomRight && roomLeft > roomRight)
        side = 'left';
      if (side === 'left' && width > roomLeft && roomRight > roomLeft)
        side = 'right';
      let left =
        side === 'right'
          ? anchorRect.right + gap
          : side === 'left'
            ? anchorRect.left - width - gap
            : alignment === 'end'
              ? anchorRect.right - width
              : alignment === 'center'
                ? anchorRect.left + (anchorRect.width - width) / 2
                : anchorRect.left;
      left = Math.min(
        Math.max(VIEWPORT_GUTTER, left),
        Math.max(VIEWPORT_GUTTER, window.innerWidth - width - VIEWPORT_GUTTER),
      );
      const desiredTop =
        side === 'top'
          ? anchorRect.top - height - gap
          : side === 'bottom'
            ? anchorRect.bottom + gap
            : alignment === 'end'
              ? anchorRect.bottom - height
              : alignment === 'center'
                ? anchorRect.top + (anchorRect.height - height) / 2
                : anchorRect.top;
      const top = Math.min(
        Math.max(VIEWPORT_GUTTER, desiredTop),
        Math.max(VIEWPORT_GUTTER, window.innerHeight - height - VIEWPORT_GUTTER),
      );
      setPosition({
        ready: true,
        left,
        top,
        width,
        resolvedPlacement: `${side}-${alignment}`,
      });
    }
    update();
    const observer = new ResizeObserver(update);
    observer.observe(anchor);
    observer.observe(overlay);
    window.addEventListener('resize', update);
    window.addEventListener('scroll', update, true);
    return () => {
      observer.disconnect();
      window.removeEventListener('resize', update);
      window.removeEventListener('scroll', update, true);
    };
  }, [open, placement, gap, minimumWidth, matchAnchorWidth, anchorRef, overlayRef]);
  return {
    resolvedPlacement: position.resolvedPlacement,
    style: {
      position: 'fixed',
      inset: 'auto',
      insetInline: 'auto',
      insetBlock: 'auto',
      right: 'auto',
      bottom: 'auto',
      left: position.left,
      top: position.top,
      minWidth: position.width,
      visibility: position.ready ? 'visible' : 'hidden',
    },
  };
}

sources.d6c67804f44cf32171bf00111be4703ce43d8563:
.feedback-surface {
  --feedback-face: #fff;
  --feedback-ink: #373434;
  --feedback-muted: #686565;
  --feedback-edge: #1d1b1b;
  --feedback-track: #e8e4e4;
  --feedback-soft: #f0eeee;
  --feedback-success: #356247;
  --feedback-success-soft: #edf5ef;
  --feedback-error: #a51d2d;
  --feedback-error-soft: #fff2f3;
  --feedback-warning: #80521a;
  --feedback-warning-soft: #fff5e5;
  color: var(--feedback-ink);
  color-scheme: light;
}
.feedback-surface[data-theme='dark'] {
  --feedback-face: #252323;
  --feedback-ink: #f3eeee;
  --feedback-muted: #bdb5b5;
  --feedback-edge: #b0a6a6;
  --feedback-track: #4c4545;
  --feedback-soft: #383333;
  --feedback-success: #9cd5ad;
  --feedback-success-soft: #25392c;
  --feedback-error: #ff9dab;
  --feedback-error-soft: #3b282d;
  --feedback-warning: #edc48a;
  --feedback-warning-soft: #403222;
  color-scheme: dark;
}
.feedback-icon {
  width: 24px;
  height: 24px;
  flex: none;
}
.feedback-surface .duoop-button--outline {
  --button-face: var(--feedback-face);
  --button-text: var(--feedback-ink);
  --button-edge: var(--feedback-edge);
}
.feedback-surface .duoop-button--outline:hover:not([aria-disabled='true']) {
  background: var(--feedback-soft);
}
.feedback-demo {
  width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.feedback-demo-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
}
.feedback-demo-note {
  margin: 0;
  font-size: 12px;
  line-height: 1.7;
  color: var(--feedback-muted);
}
.feedback-lab {
  margin: 0 0 48px;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.feedback-lab-heading {
  padding: 24px 28px;
  border-bottom: 1px solid var(--border);
}
.feedback-lab-heading h3 {
  margin: 0 0 8px;
  font-size: 20px;
}
.feedback-lab-heading p {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
  line-height: 1.7;
}
.feedback-lab-layout {
  display: grid;
  grid-template-columns: minmax(230px, 0.8fr) minmax(0, 1.2fr);
}
.feedback-lab-controls {
  display: grid;
  align-content: start;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
  padding: 28px;
}
.feedback-lab-controls > label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  min-width: 0;
}
.feedback-lab-controls input[type='range'] {
  width: 100%;
  margin: 0;
  appearance: none;
  height: 44px;
  background: transparent;
  padding: 0;
  accent-color: #373434;
  cursor: pointer;
}
.feedback-lab-controls input[type='range']::-webkit-slider-runnable-track {
  height: 8px;
  border: 2px solid #1d1b1b;
  border-radius: 4px;
  background: #e8e4e4;
}
.feedback-lab-controls input[type='range']::-webkit-slider-thumb {
  appearance: none;
  width: 20px;
  height: 24px;
  margin-top: -10px;
  border: 2px solid #1d1b1b;
  border-radius: 5px;
  background: #fff;
  box-shadow: 0 3px 0 #1d1b1b;
}
.feedback-lab-controls input[type='range']::-moz-range-track {
  height: 5px;
  border: 2px solid #1d1b1b;
  border-radius: 4px;
  background: #e8e4e4;
}
.feedback-lab-controls input[type='range']::-moz-range-thumb {
  width: 16px;
  height: 20px;
  border: 2px solid #1d1b1b;
  border-radius: 5px;
  background: #fff;
  box-shadow: 0 3px 0 #1d1b1b;
}
.feedback-lab-controls input[type='range']:focus-visible {
  outline: none;
  border-radius: 4px;
}
.feedback-lab-controls input[type='range']:focus-visible::-webkit-slider-thumb {
  background: #e8e4e4;
  border-style: dashed;
}
.feedback-lab-controls input[type='range']:focus-visible::-moz-range-thumb {
  background: #e8e4e4;
  border-style: dashed;
}
.feedback-lab-controls .duoop-switch {
  grid-column: 1/-1;
}
.feedback-lab-stage {
  background: var(--feedback-soft);
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 28px;
  min-width: 0;
  min-height: 330px;
}
.toast-showcase .gallery-card-preview,
.progress-showcase .gallery-card-preview {
  padding: 32px 24px;
  min-height: 280px;
  align-items: center;
}
.toast-showcase .gallery-grid,
.progress-showcase .gallery-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (max-width: 1000px) {
  .feedback-lab-layout {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 650px) {
  .toast-showcase .gallery-grid,
  .progress-showcase .gallery-grid {
    grid-template-columns: 1fr;
  }
  .feedback-lab-stage {
    padding: 28px 20px;
  }
  .feedback-lab-controls,
  .feedback-lab-heading {
    padding: 20px;
  }
  .toast-showcase .gallery-card-preview,
  .progress-showcase .gallery-card-preview {
    padding: 28px 20px;
  }
}
.feedback-lab-controls .duoop-select-field {
  min-width: 0;
}
.feedback-lab-controls .duoop-select {
  min-width: 0;
}
@media (max-width: 500px) {
  .feedback-lab-controls {
    grid-template-columns: minmax(0, 1fr);
  }
}

