}
.experience-surface[data-theme='dark'] .duoop-button:disabled {
  --button-face: #383333;
  --button-text: #bdb5b5;
  --button-edge: #746a6a;
}
.experience-surface .duoop-checkbox {
  --check-fg: var(--feedback-ink);
  --check-muted: var(--feedback-muted);
  --check-bg: var(--feedback-face);
  --check-border: var(--feedback-edge);
  --check-soft: var(--feedback-soft);
  --check-error: var(--feedback-error);
  --check-shadow: var(--feedback-edge);
}
@media (max-width: 700px) {
  .stepper-showcase .gallery-grid,
  .reaction-button-showcase .gallery-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .stepper-showcase .gallery-card-preview,
  .reaction-button-showcase .gallery-card-preview {
    padding: 28px 20px;
  }
}

