  position: absolute;
  inset: 50% auto auto 22px;
  width: 1px;
  height: 1px;
  color: var(--feedback-ink, #373434);
}
.reaction-particles i {
  position: absolute;
  width: 4px;
  height: 7px;
  border-radius: 1px;
  background: currentColor;
  opacity: 0;
  animation: reaction-particle 480ms ease-out both;
  --particle-distance: 40px;
}
.reaction-summary {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 13px;
}
.reaction-summary-marks {
  display: flex;
  padding-inline-end: 6px;
}
.reaction-summary-marks > span,
.reaction-person-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 2px solid var(--feedback-edge, #1d1b1b);
  border-radius: 8px;
  background: var(--feedback-face, #fff);
  box-shadow: 0 3px 0 var(--feedback-edge, #1d1b1b);
}
.reaction-summary-marks > span + span {
  margin-inline-start: -6px;
}
.reaction-summary-marks svg,
.reaction-person-icon svg {
  width: 20px;
  height: 20px;
}
.reaction-picker {
  z-index: 1200;
  max-width: calc(100vw - 24px);
  padding: 16px;
  border: 2px solid var(--feedback-edge);
  border-radius: 10px;
  background: var(--feedback-face);
  box-shadow: 0 5px 0 var(--feedback-edge);
  animation: reaction-picker-in 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.reaction-picker > p {
  font-size: 12px;
  font-weight: 650;
  margin: 0 0 14px;
}
.reaction-picker > div {
  display: grid;
  grid-template-columns: repeat(3, 44px);
  gap: 14px;
  justify-content: space-between;
}
.reaction-picker svg {
  width: 20px;
  height: 20px;
}
.reaction-detail-filters {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}
.reaction-details ul {
  padding: 0;
  margin: 0 0 16px;
  list-style: none;
}
.reaction-details li {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 0;
  border-bottom: 1px solid var(--feedback-track);
}
.reaction-details li > span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.reaction-details strong {
  display: block;
  font-size: 13px;
}
.reaction-details small {
  display: block;
  font-size: 12px;
  color: var(--feedback-muted);
  margin-top: 5px;
}
.reaction-details li > svg {
  width: 20px;
  height: 20px;
}
.reaction-editorial {
  border-block-start: 2px solid var(--feedback-edge);
  padding-top: 20px;
  display: grid;
  gap: 20px;
}
.reaction-editorial h4 {
  font-size: 21px;
  line-height: 1.3;
  letter-spacing: -0.5px;
}
.reaction-editorial > p {
  font-size: 13px;
  line-height: 1.8;
  color: var(--feedback-muted);
  margin: 0;
}
@keyframes reaction-pop {
  0% {
    transform: scale(0.75) rotate(-12deg);
  }
  55% {
    transform: scale(1.3) rotate(8deg);
  }
  to {
    transform: none;
  }
}
@keyframes reaction-count-in {
  from {
    opacity: 0.4;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes reaction-fade {
  from {
    opacity: 0.35;
  }
  to {
    opacity: 1;
  }
}
@keyframes reaction-particle {
  0% {
    opacity: 0;
    transform: rotate(var(--particle-angle)) translateY(-10px) scale(0.4);
  }
  20% {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: rotate(var(--particle-angle))
      translateY(calc(-1 * var(--particle-distance))) scale(0.4);
  }
}
@keyframes reaction-picker-in {
  from {
    opacity: 0;
    translate: 0 6px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .reaction-glyph,
  .reaction-count,
  .reaction-picker,
  .reaction-particles i {
    animation: none !important;
    transition: none;
  }
  .reaction-particles {
    display: none;
  }
}

.reaction-button-showcase .experience-state-list > div:has(> .experience-kicker) {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}
.reaction-button-showcase .experience-state-list {
  gap: 28px;
}

