.duoop-select-field {
  position: relative;
  display: grid;
  gap: 7px;
  width: max-content;
  max-width: 100%;
  color: #373434;
  font-size: 13px;
}
.duoop-select-field > label {
  font-weight: 600;
}
.duoop-select-field--fixed {
  width: 280px;
}
.duoop-select-field--full {
  width: 100%;
}
.duoop-select__help,
.duoop-select__error {
  font-size: 11px;
  line-height: 1.5;
  color: #686565;
}
.duoop-select__error {
  color: #a51d2d;
}
.duoop-select {
  --select-face: #fff;
  --select-edge: #373434;
  min-width: 220px;
  max-width: 100%;
  height: 48px;
  padding: 0 13px 0 15px;
  border: 2px solid var(--select-edge);
  border-radius: 10px;
  background: var(--select-face);
  box-shadow: 0 3px 0 #1d1b1b;
  color: #373434;
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
  font: 500 13px/1.3 inherit;
  cursor: pointer;
  transition:
    transform 100ms ease,
    box-shadow 120ms ease,
    background 150ms ease;
}
.duoop-select > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
}
.duoop-select > span[data-placeholder] {
  color: #777474;
}
.duoop-select > svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  flex: none;
  transition: transform 200ms ease;
}
.duoop-select[aria-expanded='true'] > svg {
  transform: rotate(180deg);
}
.duoop-select:hover:not(:disabled) {
  background: #f4f2f2;
}
.duoop-select:active:not(:disabled) {
  transform: translateY(2px);
  box-shadow: 0 1px 0 #1d1b1b;
}
.duoop-select:focus-visible {
  outline: none;
}
.duoop-select:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.duoop-select[aria-invalid='true'] {
  --select-edge: #a51d2d;
  background: #fff5f5;
  box-shadow: 0 3px 0 #761725;
}
.duoop-select--sm {
  height: 40px;
  min-width: 180px;
}
.duoop-select--lg {
  height: 56px;
  min-width: 260px;
  font-size: 14px;
}
.duoop-select--ghost {
  border-color: transparent;
  box-shadow: none;
}
.duoop-select--filled {
  background: #f0eeee;
}
.duoop-select-field--full .duoop-select {
  width: 100%;
}
.duoop-select__popup {
  position: absolute;
  z-index: 30;
  inset-block-start: calc(100% + 9px);
  inset-inline: 0;
  min-width: max(100%, 240px);
  animation: select-open 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
  transform-origin: top;
}
.duoop-select__popup ul {
  list-style: none;
  margin: 0;
  padding: 7px;
  max-height: 280px;
  overflow: auto;
  overscroll-behavior: contain;
  border: 2px solid #373434;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 5px 0 #1d1b1b;
}
.duoop-select__popup [role='option'] {
  min-height: 42px;
  padding: 8px 10px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
}
.duoop-select__popup [role='option'][data-active] {
  background: #f0eeee;
}
.duoop-select__popup [role='option'][aria-disabled='true'] {
  opacity: 0.4;
  cursor: not-allowed;
}
.duoop-select__option-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
  flex: 1;
}
.duoop-select__option-copy strong {
  font-size: 12px;
  font-weight: 600;
}
.duoop-select__option-copy small {
  font-size: 11px;
  color: #686565;
}
.duoop-select__option-meta {
  font-size: 10px;
  color: #686565;
}
.duoop-select__option-icon {
  display: grid;
  place-items: center;
}
.duoop-select__option-icon svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
}
.duoop-select__check {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: #373434;
  stroke-width: 2.2;
  opacity: 0;
  transform: scale(0.7);
  transition:
    opacity 120ms ease,
    transform 160ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
[role='option'][data-selected] .duoop-select__check {
  opacity: 1;
  transform: scale(1);
}
.duoop-select__group {
  padding: 9px 10px 5px;
  color: #686565;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.duoop-select__separator {
  height: 1px;
  background: #e0dddd;
  margin: 6px;
}
.duoop-select__popup * {
  scrollbar-width: thin;
  scrollbar-color: #aaa5a5 transparent;
}
@keyframes select-open {
  from {
    opacity: 0;
    transform: translateY(-5px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-select,
  .duoop-select > svg,
  .duoop-select__popup,
  .duoop-select__check {
    animation: none;
    transition: none;
  }
}

