sources.b6999d3840f7c20afe2f68ab2165c44bac4f78db:
import React, { useId } from 'react';
import './Selection.css';

/** Native radios preserve arrow navigation, form values and clickable labels. */
export function RadioGroup({
  legend,
  name,
  options,
  value,
  defaultValue,
  onChange,
  description,
  error,
  required = false,
  disabled = false,
  layout = 'vertical',
  variant = 'plain',
  indicator = 'start',
  className = '',
  children,
  ...props
}) {
  const id = useId();
  const help =
    [props['aria-describedby'], description && `${id}-help`, error && `${id}-error`]
      .filter(Boolean)
      .join(' ') || undefined;
  return (
    <fieldset
      {...props}
      disabled={disabled}
      className={`selection-group ${className}`}
      aria-describedby={help}
      aria-invalid={error ? true : undefined}
      data-invalid={!!error}
    >
      <legend>
        {legend}
        {required && <small> (required)</small>}
      </legend>
      {description && (
        <p className="selection-help" id={`${id}-help`}>
          {description}
        </p>
      )}
      <div
        className={`radio-options radio-options--${layout} radio-options--${variant}`}
      >
        {options.map((option) => {
          const optionId = `${id}-${option.value}`;
          return (
            <label
              key={option.value}
              className={`radio-option radio-option--${variant}`}
              data-indicator={indicator}
            >
              <span className="radio-control">
                <input
                  type="radio"
                  name={name || id}
                  value={option.value}
                  disabled={option.disabled}
                  required={required}
                  checked={value !== undefined ? value === option.value : undefined}
                  defaultChecked={
                    value === undefined ? defaultValue === option.value : undefined
                  }
                  onChange={onChange}
                  aria-labelledby={`${optionId}-label`}
                  aria-describedby={
                    [help, option.description && `${optionId}-description`]
                      .filter(Boolean)
                      .join(' ') || undefined
                  }
                  aria-invalid={error ? true : undefined}
                />
                <span className="radio-disc" aria-hidden="true">
                  <span />
                </span>
              </span>
              <span className="selection-content">
                {option.image && (
                  <span className="selection-image" aria-hidden="true">
                    {option.image}
                  </span>
                )}
                {option.swatch && (
                  <span
                    className="selection-swatch"
                    style={{ background: option.swatch }}
                    aria-hidden="true"
                  />
                )}
                <span className="selection-title">
                  <span id={`${optionId}-label`}>
                    {option.icon && (
                      <span className="selection-icon" aria-hidden="true">
                        {option.icon}
                      </span>
                    )}
                    {option.label}
                  </span>
                  {option.badge && (
                    <span className="selection-badge">{option.badge}</span>
                  )}
                </span>
                {option.price && (
                  <span className="selection-price">
                    {option.price}
                    <small> / month</small>
                  </span>
                )}
                {option.description && (
                  <span className="selection-help" id={`${optionId}-description`}>
                    {option.description}
                  </span>
                )}
                {option.features && (
                  <span className="selection-features">
                    {option.features.map((feature) => (
                      <span key={feature}>✓ {feature}</span>
                    ))}
                  </span>
                )}
              </span>
            </label>
          );
        })}
      </div>
      {children}
      <div aria-live="polite">
        {error && (
          <p className="selection-error" id={`${id}-error`}>
            {error}
          </p>
        )}
      </div>
    </fieldset>
  );
}

/** Controlled and uncontrolled binary switch; onChange receives a native event. */
export function Switch({
  label,
  description,
  error,
  size = 'default',
  position = 'start',
  variant = 'plain',
  icon,
  internalIcons = false,
  showState = false,
  pending = false,
  className = '',
  id,
  ...props
}) {
  const generated = useId();
  const controlId = id || generated;
  const help =
    [
      props['aria-describedby'],
      description && `${controlId}-help`,
      error && `${controlId}-error`,
    ]
      .filter(Boolean)
      .join(' ') || undefined;
  return (
    <div
      className={`duoop-switch duoop-switch--${size} duoop-switch--${variant} ${className}`}
      data-invalid={!!error}
    >
      <label className="switch-label" htmlFor={controlId} data-position={position}>
        <span className="switch-control">
          <input
            {...props}
            id={controlId}
            type="checkbox"
            role="switch"
            aria-describedby={help}
            aria-invalid={error ? true : props['aria-invalid']}
            aria-busy={pending || undefined}
            disabled={props.disabled || pending}
          />
          <span className="switch-track" aria-hidden="true">
            {internalIcons && (
              <span className="switch-track-icons">
                <span>✓</span>
                <span>−</span>
              </span>
            )}
            <span className="switch-thumb">
              {pending && <span className="switch-spinner" />}
            </span>
          </span>
        </span>
        {label && (
          <span className="selection-content">
            <span className="selection-title">
              {icon && (
                <span className="selection-icon" aria-hidden="true">
                  {icon}
                </span>
              )}
              {label}
              {props.required && <small> (required)</small>}
            </span>
            {description && (
              <span className="selection-help" id={`${controlId}-help`}>
                {description}
              </span>
            )}
          </span>
        )}
        {showState && (
          <span className="switch-state" aria-hidden="true">
            <span className="switch-state-on">Enabled</span>
            <span className="switch-state-off">Disabled</span>
          </span>
        )}
      </label>
      {!label && description && (
        <p className="selection-help" id={`${controlId}-help`}>
          {description}
        </p>
      )}
      <div aria-live="polite">
        {error && (
          <p className="selection-error" id={`${controlId}-error`}>
            {error}
          </p>
        )}
      </div>
    </div>
  );
}

sources.9a24c1399636349c178cea5fbf464ea7e8112c04:
.selection-group,
.duoop-switch,
.selection-surface {
  color: var(--selection-fg, #373434);
  font-size: 13px;
  line-height: 1.5;
  min-width: 0;
}
.selection-surface {
  --selection-fg: #373434;
  --selection-muted: #686565;
  --selection-bg: #fff;
  --selection-border: #777474;
  --selection-soft: #f0eeee;
  --selection-shadow: #1d1b1b;
  --selection-error: #a51d2d;
  padding: 24px;
  border-radius: 10px;
  background: var(--selection-bg);
}
.selection-surface[data-theme='dark'] {
  --selection-fg: #f3eeee;
  --selection-muted: #bdb5b5;
  --selection-bg: #252323;
  --selection-border: #b0a6a6;
  --selection-soft: #383333;
  --selection-shadow: #111;
  --selection-error: #ff9dab;
  color-scheme: dark;
}
.selection-group {
  border: 0;
  padding: 0;
  margin: 0;
  width: 100%;
}
.selection-group legend {
  font-size: 13px;
  font-weight: 600;
  padding: 0;
  margin-bottom: 12px;
}
.selection-group small,
.selection-title small {
  font-size: 11px;
  font-weight: 400;
}
.selection-help {
  display: block;
  margin: 0;
  color: var(--selection-muted, #686565);
  font-size: 12px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}
.selection-group > .selection-help {
  margin-bottom: 14px;
}
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.radio-options--horizontal {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px 24px;
}
.radio-options--grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 160px), 1fr));
  gap: 16px;
}
.radio-option,
.switch-label {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  margin: 0;
  padding: 10px 0;
  cursor: pointer;
  font: inherit;
  position: relative;
}
.radio-option {
  align-items: flex-start;
}
.selection-content {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}
.selection-title {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 550;
  overflow-wrap: anywhere;
}
.selection-icon {
  display: inline-block;
  margin-inline-end: 8px;
  font-size: 19px;
  vertical-align: middle;
}
.selection-icon svg {
  display: block;
}
.selection-badge {
  border: 1px solid var(--selection-border, #777474);
  border-radius: 5px;
  padding: 1px 6px;
  font-size: 10px;
  font-weight: 500;
}
.radio-control {
  flex: 0 0 20px;
  width: 20px;
  height: 20px;
  position: relative;
  margin-block: 1px;
}
.radio-control input,
.switch-control input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-height: 0;
  margin: 0;
  padding: 0;
  opacity: 0;
  cursor: inherit;
  z-index: 1;
}
.radio-control input:focus,
.switch-control input:focus {
  outline: none;
}
.radio-disc {
  position: absolute;
  inset: 0;
  border: 2px solid var(--selection-border, #777474);
  border-radius: 50%;
  background: var(--selection-bg, #fff);
  box-shadow: 0 2px 0 var(--selection-border, #777474);
  display: grid;
  place-items: center;
  transition:
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 120ms ease,
    border-color 140ms ease,
    background-color 140ms ease;
}
.radio-disc > span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--selection-fg, #373434);
  transform: scale(0);
  opacity: 0;
  transition:
    transform 180ms cubic-bezier(0.2, 1.5, 0.4, 1),
    opacity 120ms ease;
}
.radio-control input:checked + .radio-disc {
  border-color: var(--selection-fg, #373434);
  box-shadow: 0 2px 0 var(--selection-shadow, #1d1b1b);
}
.radio-control input:checked + .radio-disc > span {
  opacity: 1;
  transform: scale(1);
}
.radio-option:hover:not(:has(:disabled)) .radio-disc {
  border-color: var(--selection-fg, #373434);
}
.radio-option:active:not(:has(:disabled)) .radio-disc {
  transform: translateY(2px) scale(0.94);
  box-shadow: 0 0 0 var(--selection-shadow, #1d1b1b);
}
.radio-control input:focus-visible + .radio-disc,
.switch-control input:focus-visible + .switch-track {
  border-style: dashed;
  outline: none;
}
.radio-option--row,
.radio-option--card {
  padding: 18px;
  border: 2px solid var(--selection-border, #777474);
  border-radius: 10px;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 140ms ease;
}
.radio-option--row:has(:checked),
.radio-option--card:has(:checked) {
  background: var(--selection-soft, #f0eeee);
  border-color: var(--selection-fg, #373434);
  box-shadow: 0 3px 0 var(--selection-shadow, #1d1b1b);
}
.radio-option--row:hover:not(:has(:disabled)),
.radio-option--card:hover:not(:has(:disabled)) {
  background: var(--selection-soft, #f0eeee);
  transform: translateY(-1px);
}
.radio-option--row:active:not(:has(:disabled)),
.radio-option--card:active:not(:has(:disabled)) {
  transform: translateY(2px);
  box-shadow: 0 0 0 var(--selection-shadow, #1d1b1b);
}
.radio-option[data-indicator='corner'] {
  padding-top: 48px;
}
.radio-option[data-indicator='corner'] .radio-control {
  position: absolute;
  inset-inline-end: 16px;
  inset-block-start: 16px;
}
.radio-options--list {
  gap: 0;
  border: 2px solid var(--selection-border, #777474);
  border-radius: 10px;
  overflow: hidden;
}
.radio-option--list {
  padding: 16px;
}
.radio-option--list + .radio-option--list {
  border-top: 1px solid var(--selection-border, #777474);
}
.radio-option--list:has(:checked),
.radio-option--list:hover:not(:has(:disabled)) {
  background: var(--selection-soft, #f0eeee);
}
.radio-option:has(:disabled),
.switch-label:has(:disabled) {
  opacity: 0.48;
  cursor: not-allowed;
}
.selection-price {
  font-size: 25px;
  font-weight: 600;
  margin-block: 6px;
  letter-spacing: -0.7px;
}
.selection-price small {
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--selection-muted, #686565);
}
.selection-features {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 10px;
  font-size: 12px;
}
.selection-swatch {
  width: 100%;
  height: 76px;
  border: 1px solid var(--selection-border, #777474);
  border-radius: 6px;
}
.selection-image {
  display: block;
  margin-bottom: 12px;
}
.selection-image svg {
  width: 100%;
  height: 110px;
  display: block;
  transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.radio-option:hover .selection-image svg,
.radio-option:has(:checked) .selection-image svg {
  transform: translateY(-3px) rotate(-1deg);
}
.duoop-switch {
  --switch-width: 44px;
  --switch-height: 26px;
  --switch-travel: 18px;
}
.duoop-switch--sm {
  --switch-width: 36px;
  --switch-height: 22px;
  --switch-travel: 14px;
}
.duoop-switch--lg {
  --switch-width: 54px;
  --switch-height: 32px;
  --switch-travel: 22px;
}
.switch-control {
  position: relative;
  width: var(--switch-width);
  height: var(--switch-height);
  flex: 0 0 var(--switch-width);
}
.switch-track {
  position: absolute;
  inset: 0;
  border: 2px solid var(--selection-border, #777474);
  border-radius: 40px;
  background: var(--selection-soft, #f0eeee);
  box-shadow: 0 2px 0 var(--selection-border, #777474);
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    box-shadow 120ms ease,
    transform 120ms ease;
}
.switch-thumb {
  position: absolute;
  inset-block-start: 3px;
  inset-inline-start: 3px;
  width: calc(var(--switch-height) - 10px);
  height: calc(var(--switch-height) - 10px);
  border-radius: 50%;
  background: var(--selection-bg, #fff);
  box-shadow: 0 1px 2px #0005;
  border: 1px solid var(--selection-border, #777474);
  display: grid;
  place-items: center;
  transition:
    translate 210ms cubic-bezier(0.2, 1.2, 0.35, 1),
    scale 100ms ease;
}
.switch-control input:checked + .switch-track {
  background: var(--selection-fg, #373434);
  border-color: var(--selection-fg, #373434);
  box-shadow: 0 2px 0 var(--selection-shadow, #1d1b1b);
}
.switch-control input:checked + .switch-track .switch-thumb {
  translate: var(--switch-travel) 0;
}
[dir='rtl'] .switch-control input:checked + .switch-track .switch-thumb {
  translate: calc(-1 * var(--switch-travel)) 0;
}
.switch-label:hover:not(:has(:disabled)) .switch-track {
  border-color: var(--selection-fg, #373434);
}
.switch-label:active:not(:has(:disabled)) .switch-track {
  transform: translateY(1px);
  box-shadow: 0 1px 0 var(--selection-shadow, #1d1b1b);
}
.switch-label:active:not(:has(:disabled)) .switch-thumb {
  scale: 1.12 0.94;
}
.switch-label[data-position='end'] .switch-control {
  order: 3;
  margin-inline-start: auto;
}
.switch-state {
  font-size: 11px;
  color: var(--selection-muted, #686565);
  min-width: 52px;
}
.switch-state-on,
.switch-label:has(:checked) .switch-state-off {
  display: none;
}
.switch-label:has(:checked) .switch-state-on {
  display: inline;
}
.switch-track-icons {
  position: absolute;
  inset: 0 4px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 10px;
  color: var(--selection-muted, #686565);
}
.switch-control input:checked + .switch-track .switch-track-icons {
  color: var(--selection-bg, #fff);
}
.duoop-switch--card .switch-label {
  border: 2px solid var(--selection-border, #777474);
  border-radius: 10px;
  padding: 18px;
  transition:
    background-color 160ms ease,
    box-shadow 160ms ease;
}
.duoop-switch--card .switch-label:has(:checked) {
  background: var(--selection-soft, #f0eeee);
  box-shadow: 0 3px 0 var(--selection-shadow, #1d1b1b);
}
.duoop-switch--row .switch-label {
  padding-block: 16px;
}
.switch-spinner {
  width: 10px;
  height: 10px;
  border: 2px solid var(--selection-border, #777474);
  border-top-color: transparent;
  border-radius: 50%;
  animation: selection-spin 650ms linear infinite;
}
@keyframes selection-spin {
  to {
    rotate: 360deg;
  }
}
.selection-error {
  font-size: 12px;
  line-height: 1.7;
  color: var(--selection-error, #a51d2d);
  margin: 12px 0 0;
  animation: selection-reveal 220ms ease-out;
}
[data-invalid='true'].selection-group,
[data-invalid='true'].duoop-switch {
  --selection-fg: var(--selection-error, #a51d2d);
  --selection-border: var(--selection-error, #a51d2d);
  --selection-shadow: var(--selection-error, #a51d2d);
  --selection-soft: #fff2f3;
}
.selection-surface[data-theme='dark'] [data-invalid='true'] {
  --selection-soft: #3b282d;
}
.selection-reveal {
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--selection-border, #777474);
