}
.enriched-demo {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.enriched-demo .form-notice:empty {
  display: none;
}
.mini-textarea {
  min-height: 86px;
  white-space: normal;
}
@media (prefers-reduced-motion: reduce) {
  .duoop-input-group {
    transition: none;
  }
}
/* Compound controls use one border and one focus treatment. */
.duoop-textarea {
  scrollbar-width: thin;
  scrollbar-color: #aaa5a5 transparent;
}
.textarea-resizable {
  position: relative;
  width: 100%;
  min-width: 0;
  padding-bottom: 18px;
  border: 2px solid #777474;
  border-radius: 10px;
  background: #fff;
  transition:
    border-color 140ms ease,
    box-shadow 180ms ease-out;
}
.textarea-resizable:hover {
  border-color: #373434;
}
.textarea-resizable:focus-within {
  outline: none;
  border-color: #373434;
  box-shadow: 0 3px 0 #373434;
}
.textarea-resizable > .duoop-textarea {
  border: 0;
  border-radius: 8px;
  box-shadow: none;
}
.textarea-resize-handle {
  position: absolute;
  bottom: 0;
  left: calc(50% - 24px);
  width: 48px;
  height: 24px;
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  cursor: ns-resize;
  touch-action: none;
  padding: 0;
}
.textarea-resize-handle span {
  width: 24px;
  height: 3px;
  border-radius: 3px;
  background: #b3adad;
  transition: background 140ms ease;
}
.textarea-resize-handle:hover span,
.textarea-resize-handle:focus-visible span {
  background: #373434;
}
.textarea-resize-handle:focus-visible {
  outline: none;
  border-radius: 4px;
}
.duoop-input[type='search']::-webkit-search-cancel-button,
.duoop-input[type='search']::-webkit-search-decoration {
  -webkit-appearance: none;
  appearance: none;
}
.group-icon-action,
.group-loading-action {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #686565;
  transition:
    background 140ms ease,
    color 140ms ease,
    transform 140ms ease;
}
.group-icon-action:hover,
.group-loading-action:hover {
  background: #efeded;
  color: #252323;
}
.group-icon-action:active,
.group-loading-action:active {
  transform: scale(0.94);
}
.group-icon-action:focus,
.group-loading-action:focus {
  outline: none;
}
.group-icon-action:focus-visible,
.group-loading-action:focus-visible {
  background: #e5e1e1;
  color: #252323;
  box-shadow: inset 0 -2px #373434;
}
.group-icon-action--send .form-icon {
  width: 22px;
  height: 22px;
}
.group-send-action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 32px;
  padding: 5px 4px 5px 12px;
  border: 0;
  border-left: 1px solid #dedada;
  border-radius: 0;
  background: transparent;
  color: #373434;
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}
.group-send-action .form-icon {
  width: 19px;
  height: 19px;
  transition: transform 160ms ease;
}
.group-send-action:hover .form-icon {
  transform: translateX(2px);
}
.group-send-action:active .form-icon {
  transform: translateX(3px) scale(0.94);
}
.group-send-action:focus {
  outline: none;
}
.group-send-action:focus-visible {
  background: #efeded;
  box-shadow: inset 0 -2px #373434;
  border-radius: 4px;
}
.group-status {
  font-size: 11px;
  line-height: 1.5;
  color: #777171;
}
.group-status:empty {
  display: none;
}
.group-loader {
  display: block;
  width: 18px;
  height: 18px;
  border: 2px solid #ddd8d8;
  border-top-color: #373434;
  border-radius: 50%;
  animation: duoop-spin 0.75s linear infinite;
}
.message-composer {
  padding: 0;
  gap: 0;
  overflow: hidden;
}
.message-composer > .duoop-textarea {
  margin: 0;
  padding: 16px;
  min-height: 144px;
  border-radius: 0;
}
.message-composer .composer-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 52px;
  padding: 10px 14px;
  background: #f8f7f7;
}
.composer-toolbar.input-group-addon--block-start {
  border-bottom: 1px solid #e8e5e5;
}
.composer-toolbar.input-group-addon--block-end {
  border-top: 1px solid #e8e5e5;
}
.composer-label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #686565;
  font-size: 12px;
  font-weight: 500;
}
.composer-count {
  color: #686565;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.composer-toolbar .group-send-action {
  border: 0;
  border-radius: 6px;
  padding: 6px 10px;
  background: #eae7e7;
}
.composer-toolbar .group-send-action:hover {
  background: #e1dddd;
}
@media (prefers-reduced-motion: reduce) {
  .group-loader {
    animation: none;
    border-style: solid;
  }
  .group-icon-action,
  .group-loading-action,
  .group-send-action .form-icon,
  .textarea-resizable,
  .textarea-resize-handle span {
    transition: none;
  }
}
.textarea-resize-handle:focus {
  outline: none;
}
.textarea-resize-handle:focus-visible {
  outline: none;
  background: #efeded;
}
@supports selector(::-webkit-scrollbar) {
  .duoop-textarea {
    scrollbar-width: auto;
    scrollbar-color: auto;
  }
}
[data-done='true'] .form-icon {
  animation: send-confirm 300ms ease-out;
  color: #356247;
}
[data-done='true'] .form-icon path {
  stroke-dasharray: 32;
  animation: send-trace 280ms ease-out;
}
@keyframes send-confirm {
  from {
    transform: scale(0.65) rotate(-15deg);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}
@keyframes send-trace {
  from {
    stroke-dashoffset: 32;
  }
  to {
    stroke-dashoffset: 0;
  }
}
.duoop-input-group:has([aria-invalid='true']) {
  background: #fff5f5;
  color: #a51d2d;
}
@media (prefers-reduced-motion: reduce) {
  [data-done='true'] .form-icon,
  [data-done='true'] .form-icon path {
    animation: none;
  }
}

sources.6ad7f5cb92be6c546e1b1812a7ff5527b5b767ed:
import React, { useEffect, useId, useRef, useState } from 'react';

import {
  InputGroup,
  InputGroupAddon as Addon,
  InputGroupInput,
  InputGroupTextarea,
  InputGroupText as Text,
} from './InputGroup';

import { Textarea } from './Textarea';

import { Field } from './Input';

import { Button, ActionFeedback } from '../Button/Button';

export function FormIcon({ name = 'search' }) {
  const paths = {
    search: 'm21 21-5-5 M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
    mail: 'M3 5h18v14H3z m0 0 9 8 9-8',
    lock: 'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',
    eye: 'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
    close: 'm6 6 12 12 M6 18 18 6',
    copy: 'M8 8h13v13H8z M16 8V3H3v13h5',
    send: 'm3 3 18 9-18 9 4-9z M7 12h14',
    info: 'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    check: 'm5 12 4 4L19 6',
  };

  return (
    <svg
      className="form-icon"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d={paths[name] || paths.search} />
    </svg>
  );
}

function IconButton({ name, label, selected, ...props }) {
  return (
    <button
      type="button"
      className={`group-icon-action ${name === 'send' ? 'group-icon-action--send' : ''}`}
      aria-label={label}
      aria-pressed={selected}
      {...props}
    >
      <FormIcon name={name} />
    </button>
  );
}

function SendAction({ done, iconOnly = false }) {
  return (
    <button
      type="submit"
      data-done={done || undefined}
      className={
        iconOnly ? 'group-icon-action group-icon-action--send' : 'group-send-action'
      }
      aria-label={
        iconOnly ? (done ? 'Message prepared' : 'Send message') : undefined
      }
    >
      {!iconOnly && <span>{done ? 'Ready' : 'Send'}</span>}
      <FormIcon key={String(done)} name={done ? 'check' : 'send'} />
    </button>
  );
}

function LoadingDemo() {
  const [value, setValue] = useState('');

  const [status, setStatus] = useState('idle');

  useEffect(() => {
    if (status !== 'loading') return;
    const timer = setTimeout(() => setStatus('done'), 1200);
    return () => clearTimeout(timer);
  }, [status, value]);

  return (
    <form
      className="enriched-demo"
      onSubmit={(event) => {
        event.preventDefault();
        if (value.trim()) setStatus('loading');
      }}
    >
      <InputGroup>
        <InputGroupInput
          aria-label="Search the library"
          placeholder="Find a component…"
          value={value}
          onChange={(event) => {
            setValue(event.target.value);
            setStatus('idle');
          }}
        />

        <Addon>
          <FormIcon name="search" />
        </Addon>
        <Addon align="inline-end">
          <button
            type="submit"
            className="group-loading-action"
            disabled={!value.trim() || status === 'loading'}
            aria-label={status === 'loading' ? 'Searching' : 'Run demo search'}
          >
            {status === 'loading' ? (
              <span className="group-loader" aria-hidden="true" />
            ) : (
              <FormIcon name={status === 'done' ? 'check' : 'send'} />
            )}
          </button>
        </Addon>
      </InputGroup>
      <span className="group-status" role="status">
        {status === 'loading'
          ? 'Searching the demo library…'
          : status === 'done'
            ? 'Demo search complete'
            : 'Type a keyword, then start the search.'}
      </span>
    </form>
  );
}

function Info() {
  const id = useId();

  const [open, setOpen] = useState(false);

  return (
    <span
      className="form-tooltip"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={() => setOpen(false)}
      onKeyDown={(event) => {
        if (event.key === 'Escape') setOpen(false);
      }}
    >
      <IconButton
        name="info"
        label="Password requirements"
        aria-describedby={open ? id : undefined}
        onClick={() => setOpen(true)}
      />
      {open && (
        <span role="tooltip" id={id}>
          Use at least 8 characters.
        </span>
      )}
    </span>
  );
}

export function GroupDemo({ variant = 'start-icon', size = 'default' }) {
  const [value, setValue] = useState(
    variant === 'copy'
      ? 'duoop.design'
      : variant === 'password'
        ? 'Design-system-26'
        : variant === 'clear'
          ? 'Input group'
          : '',
  );

  const [shown, setShown] = useState(false);

  const [notice, setNotice] = useState('');

  const input = useRef(null);

  const id = useId();

  async function copy() {
    try {
      await navigator.clipboard.writeText(`https://${value}`);
      setNotice('URL copied.');
    } catch {
      setNotice('Copy unavailable. Select and copy the URL manually.');
      input.current.focus();
      input.current.select();
    }
  }

  const startIcon = [
    'start-icon',
    'both-icons',
    'clear',
    'password',
    'shortcut',
  ].includes(variant);

  const prefix = ['prefix', 'both-text', 'copy'].includes(variant);

  const numeric = ['number', 'amount', 'suffix'].includes(variant);

  const send = ['send', 'text-button', 'icon-button'].includes(variant);

  function submit(event) {
    event.preventDefault();
    if (!send) return;
    setNotice(value.trim() ? 'Message prepared' : 'Enter a message first.');
    if (!value.trim()) input.current.focus();
  }

  if (variant === 'loading') return <LoadingDemo />;

  const group = (
    <InputGroup size={size}>
      <InputGroupInput
        ref={input}
        id={id}
        aria-label={
          variant === 'label'
            ? undefined
            : ['password', 'tooltip'].includes(variant)
              ? 'Password'
              : variant === 'clear'
                ? 'Search components'
                : variant === 'copy'
                  ? 'Website URL'
                  : numeric
                    ? 'Amount'
                    : send
                      ? 'Message'
                      : 'Input group example'
        }
        type={
          (variant === 'password' && !shown) || variant === 'tooltip'
            ? 'password'
            : variant === 'clear'
              ? 'search'
              : numeric
                ? 'number'
                : 'text'
        }
        step={numeric ? '0.01' : undefined}
        value={value}
        onChange={(event) => {
          setValue(event.target.value);
          setNotice('');
        }}
        placeholder={numeric ? '0.00' : send ? 'Write a message…' : 'Enter a value…'}
      />

      {startIcon && (
        <Addon>
          <FormIcon name={variant === 'password' ? 'lock' : 'search'} />
        </Addon>
      )}

      {prefix && (
        <Addon>
          <Text>https://</Text>
        </Addon>
      )}

      {variant === 'amount' && (
        <Addon>
          <Text>€</Text>
        </Addon>
      )}

      {variant === 'label' && (
        <Addon align="block-start">
          <label className="input-group-label" htmlFor={id}>
            Workspace name
          </label>
        </Addon>
      )}

      <Addon align="inline-end">
        {['end-icon', 'both-icons'].includes(variant) && <FormIcon name="mail" />}

        {variant === 'both-text' && <Text>.com</Text>}

        {['suffix', 'number'].includes(variant) && <Text>kg</Text>}

        {variant === 'amount' && <Text>EUR</Text>}

        {variant === 'clear' && (
          <IconButton
            name="close"
            label="Clear search"
            disabled={!value}
            onClick={() => {
              setValue('');
              input.current.focus();
            }}
          />
        )}

        {variant === 'password' && (
          <IconButton
            name="eye"
            label={shown ? 'Hide password' : 'Show password'}
            selected={shown}
            onClick={() => setShown(!shown)}
          />
        )}

        {variant === 'copy' && (
          <IconButton
            name={notice === 'URL copied.' ? 'check' : 'copy'}
            label="Copy URL"
            onClick={copy}
          />
        )}

        {variant === 'tooltip' && <Info />}

        {variant === 'badge' && <span className="input-group-badge">Optional</span>}

        {variant === 'shortcut' && <kbd className="input-group-kbd">Esc</kbd>}

        {send && (
          <SendAction
            done={notice === 'Message prepared'}
            iconOnly={variant === 'icon-button'}
          />
        )}
      </Addon>
    </InputGroup>
  );

  return (
    <form
      className="enriched-demo"
      onSubmit={submit}
      onKeyDown={(event) => {
        if (variant === 'shortcut' && event.key === 'Escape') {
          setValue('');
          input.current.focus();
        }
      }}
    >
      {group}
      <ActionFeedback
        tone={
          notice.includes('first') || notice.includes('unavailable')
            ? 'error'
            : 'success'
        }
      >
        {notice}
      </ActionFeedback>
    </form>
  );
}

export function MultilineDemo({ position = 'bottom' }) {
  const [value, setValue] = useState('');

  const [done, setDone] = useState(false);

  const id = useId();

  return (
    <form
      className="enriched-demo"
      onSubmit={(event) => {
        event.preventDefault();
        if (value.trim()) setDone(true);
      }}
    >
      <InputGroup className="message-composer">
        <InputGroupTextarea
          id={id}
          aria-label="Draft message"
          required
          autoSize
          spellCheck={false}
          placeholder="Share an idea with your team…"
          value={value}
          onChange={(event) => {
            setValue(event.target.value);
            setDone(false);
          }}
        />

        <Addon
          align={position === 'top' ? 'block-start' : 'block-end'}
          className="composer-toolbar"
        >
          {position === 'top' ? (
            <label htmlFor={id} className="composer-label">
              <FormIcon name="mail" />
              New message
            </label>
          ) : (
            <span className="composer-count">
              {value.length > 0
                ? `${value.length} characters`
                : 'Your next idea starts here'}
            </span>
          )}

          <SendAction done={done} />
        </Addon>
      </InputGroup>
      <ActionFeedback>{done ? 'Message prepared. Demo only.' : ''}</ActionFeedback>
    </form>
  );
}

export function TextareaDemo({ variant = 'standard', size = 'default' }) {
  const limit = 120;

  const [value, setValue] = useState(
    variant === 'limit'
      ? 'A shared component library brings clear labels, consistent feedback, and thoughtful interactions to every form we create.'
          .padEnd(limit, '.')
          .slice(0, limit)
      : variant === 'long'
        ? Array.from(
            { length: 10 },
            (_, i) =>
              `Paragraph ${i + 1}. A shared library keeps our forms consistent, accessible, and ready for the next idea.`,
          ).join('\n\n')
        : '',
  );

  const [saved, setSaved] = useState(false);

  const id = useId();

  if (variant === 'actions') return <MultilineDemo />;

  const counted = ['counter', 'limit'].includes(variant);

  const control = (
    <Textarea
      size={size}
      rows={3}
      autoSize={variant === 'auto'}
      resize={variant === 'resize' ? 'vertical' : 'none'}
      spellCheck={false}
      style={['fixed', 'long'].includes(variant) ? { height: 128 } : undefined}
      disabled={variant === 'disabled'}
      placeholder={
        variant === 'auto'
          ? 'Keep writing — this field grows with you…'
          : 'Write your message…'
      }
      aria-label="Message"
      aria-describedby={counted ? id : undefined}
      maxLength={counted ? limit : undefined}
      value={value}
      onChange={(event) => {
        setValue(event.target.value);
        setSaved(false);
      }}
      required={variant === 'form'}
      name="message"
    />
  );

  return (
    <form
      className="enriched-demo"
      onSubmit={(event) => {
        event.preventDefault();
        setSaved(true);
      }}
    >
      {['label', 'form'].includes(variant) ? (
        <Field label="Message" description="Tell us about your project.">
          {control}
        </Field>
      ) : (
        control
      )}

      {counted && (
        <p className="textarea-counter" data-limit={value.length === limit} id={id}>
          {value.length} / {limit}
          {value.length === limit ? ' · Limit reached' : ''}
        </p>
      )}

      {counted && (
        <span className="sr-only" role="status">
          {value.length === limit ? 'Character limit reached.' : ''}
        </span>
      )}

      {variant === 'form' && (
        <>
          <Button
            type="submit"
            status={saved ? 'success' : 'idle'}
            successLabel="Validated"
          >
            Validate message
          </Button>
          <ActionFeedback className="form-notice">
            {saved ? 'Message validated. This demo sends no data.' : ''}
          </ActionFeedback>
        </>
      )}
    </form>
  );
}

