import React, { useMemo } from 'react';
import { Select } from './Select';
const icons = ['grid', 'code', 'pen'].map((name) => (
  <svg key={name} viewBox="0 0 20 20">
    <rect x="3" y="3" width="14" height="14" rx="2" />
    <path d="M6 7h8M6 10h8M6 13h5" />
  </svg>
));
const base = [
  { value: 'design', label: 'Design', description: 'Interface and product craft' },
  {
    value: 'engineering',
    label: 'Engineering',
    description: 'Platform and application code',
  },
  { value: 'research', label: 'Research', description: 'Discovery and synthesis' },
  {
    value: 'operations',
    label: 'Operations',
    description: 'Delivery and support',
    disabled: true,
  },
];
function propsFor(example) {
  let options = base,
    props = { options, defaultValue: 'design' };
  if (example === 'Placeholder') props.defaultValue = null;
  if (example === 'Small') props.size = 'sm';
  if (example === 'Large') props.size = 'lg';
  if (example === 'Full width') props.width = 'full';
  if (example === 'Fixed width') props.width = 'fixed';
  if (example === 'Disabled') props.disabled = true;
  if (example === 'Disabled option') props.defaultValue = 'engineering';
  if (example === 'Invalid')
    Object.assign(props, {
      invalid: true,
      label: 'Team',
      error: 'Choose a team before continuing.',
    });
  if (example === 'Label and description')
    Object.assign(props, {
      label: 'Team',
      description: 'The group that owns this work.',
      required: true,
    });
  if (example === 'Groups and separators')
    props.options = [
      { label: 'Product', options: base.slice(0, 2) },
      { label: 'Company', options: base.slice(2) },
    ];
  if (example === 'Multiple selection')
    Object.assign(props, {
      multiple: true,
      defaultValue: ['design', 'engineering', 'research'],
    });
  if (example === 'Trigger icon')
    props.renderValue = (value, chosen) => (
      <span className="select-rich-value">
        {icons[0]}
        {chosen[0]?.label}
      </span>
    );
  if (example === 'Options with icons')
    props.options = base.map((x, i) => ({ ...x, icon: icons[i % 3] }));
  if (example === 'Options with descriptions') props.options = base;
  if (example === 'Options with metadata')
    props.options = base.map((x, i) => ({ ...x, meta: `${12 + i * 7}` }));
  if (example === 'Object values') {
    const objects = base.map((x) => ({ ...x, value: { id: x.value } }));
    props = {
      options: objects,
      defaultValue: objects[0].value,
      renderValue: (v, c) => c[0]?.label,
    };
  }
  if (example === 'Long scrollable list')
    props.options = Array.from({ length: 18 }, (_, i) => ({
      value: `item-${i}`,
      label: `Workspace ${String(i + 1).padStart(2, '0')}`,
      description: 'Available project space',
    }));
  if (example === 'Ghost') props.variant = 'ghost';
  if (example === 'Filled') props.variant = 'filled';
  if (example === 'Open') props.defaultOpen = true;
  if (example === 'Top placement')
    Object.assign(props, { defaultOpen: true, placement: 'top-start' });
  return props;
}
export const selectExamples = [
  ['Default', 'Appearance'],
  ['Placeholder', 'States'],
  ['Small', 'Size'],
  ['Large', 'Size'],
  ['Full width', 'Width'],
  ['Fixed width', 'Width'],
  ['Disabled', 'States'],
  ['Disabled option', 'States'],
  ['Invalid', 'Form'],
  ['Label and description', 'Form'],
  ['Groups and separators', 'Organization'],
  ['Multiple selection', 'Selection'],
  ['Trigger icon', 'Content'],
  ['Options with icons', 'Content'],
  ['Options with descriptions', 'Content'],
  ['Options with metadata', 'Content'],
  ['Object values', 'Value'],
  ['Long scrollable list', 'Organization'],
  ['Ghost', 'Appearance'],
  ['Filled', 'Appearance'],
  ['Open', 'States'],
  ['Top placement', 'Placement'],
];
export function SelectDemo({ example = 'Default' }) {
  const props = useMemo(() => propsFor(example), [example]);
  return <Select {...props} placeholder="Choose a team" />;
}

