.duoop-autocomplete {
  width: 100%;
  min-width: 0;
  color: #373434;
}
.autocomplete-control {
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
  min-height: 44px;
  border: 2px solid #373434;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 0 #1d1b1b;
  transition:
    box-shadow 180ms cubic-bezier(0.2, 0.8, 0.2, 1),
    border-color 140ms ease,
    background 140ms ease;
}
.autocomplete-control:hover {
  background: #fcfbfb;
}
.autocomplete-control:focus-within {
  outline: none;
}
.autocomplete-control[data-open] {
  box-shadow: 0 4px 0 #1d1b1b;
}
.autocomplete-control input {
  display: block;
  flex: 1;
  min-width: 0;
  width: 100%;
  margin: 0;
  padding: 11px 12px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  box-shadow: none;
  font: inherit;
  font-size: 14px;
  line-height: 1.4;
}
.autocomplete-control input:focus {
  outline: none;
  box-shadow: none;
}
.autocomplete-control input:focus-visible {
  box-shadow: inset 0 -2px 0 currentColor;
}
.autocomplete-control input::placeholder {
  color: #767171;
}
.autocomplete-control--sm {
  min-height: 36px;
}
.autocomplete-control--sm input {
  padding-block: 7px;
  font-size: 12px;
}
.autocomplete-control--lg {
  min-height: 52px;
}
.autocomplete-control--lg input {
  padding-block: 13px;
  font-size: 16px;
}
.autocomplete-control[data-invalid='true'] {
  color: #a51d2d;
  border-color: #a51d2d;
  background: #fff5f5;
  box-shadow: 0 3px 0 #761725;
}
.duoop-autocomplete[data-disabled] .autocomplete-control {
  background: #f0eeee;
  border-color: #aaa5a5;
  box-shadow: 0 2px 0 #aaa5a5;
  color: #686565;
}
.duoop-autocomplete[data-disabled] input {
  cursor: not-allowed;
}
.autocomplete-addon {
  display: grid;
  place-items: center;
  margin-inline-start: 12px;
}
.autocomplete-addon svg,
.autocomplete-action svg,
.autocomplete-option svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.autocomplete-action {
  flex: none;
  display: grid;
  place-items: center;
  width: 36px;
  align-self: stretch;
  margin: 2px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition:
    background 140ms ease,
    transform 100ms ease;
}
.autocomplete-action:hover:not(:disabled) {
  background: #f0eeee;
}
.autocomplete-action:active:not(:disabled) {
  transform: translateY(2px);
}
.autocomplete-action:focus-visible {
  outline: none;
}
.autocomplete-action:disabled {
  opacity: 0.35;
  cursor: default;
}
.autocomplete-trigger svg {
  transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.autocomplete-trigger[aria-expanded='true'] svg {
  transform: rotate(180deg);
}
.autocomplete-popup {
  z-index: 100;
  width: 0;
  max-width: calc(100vw - 24px);
  border: 2px solid #373434;
  border-radius: 10px;
  background: #fff;
  color: #373434;
  box-shadow: 0 5px 0 #1d1b1b;
  font-family: inherit;
  animation: autocomplete-reveal 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
  transform-origin: top;
}
.autocomplete-popup[data-side='top'] {
  transform-origin: bottom;
}
.autocomplete-list {
  max-height: min(272px, 45dvh);
  padding: 6px;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: #aaa5a5 transparent;
}
.autocomplete-list:empty {
  padding: 0;
}
.autocomplete-option {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 10px;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
  transition:
    background 140ms ease,
    border-color 140ms ease;
}
.autocomplete-option > span {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 4px;
  overflow-wrap: anywhere;
}
.autocomplete-option strong {
  font-size: 13px;
  font-weight: 500;
}
.autocomplete-option small {
  font-size: 12px;
  line-height: 1.5;
  color: #686565;
}
.autocomplete-option[data-active] {
  background: #f0eeee;
  border-color: #d1cccc;
}
.autocomplete-option svg {
  flex: none;
  width: 16px;
  height: 16px;
  opacity: 0;
  transform: translateX(-4px);
  transition:
    opacity 140ms ease,
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.autocomplete-option[data-active] svg {
  opacity: 1;
  transform: none;
}
.autocomplete-option[aria-disabled='true'] {
  opacity: 0.45;
  cursor: not-allowed;
}
.autocomplete-group {
  padding: 12px 11px 5px;
  font-size: 11px;
  font-weight: 600;
  color: #686565;
}
.autocomplete-footer {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  border-top: 1px solid #e7e9ed;
  padding: 10px 12px;
  color: #686565;
  font-size: 11px;
}
.autocomplete-empty {
  margin: 0;
  padding: 20px 16px;
  font-size: 13px;
  line-height: 1.7;
}
.autocomplete-demo {
  width: 100%;
  max-width: 360px;
  display: grid;
  gap: 20px;
}
.autocomplete-demo-note {
  margin: 0;
  font-size: 12px;
  line-height: 1.6;
  color: #686565;
}
.autocomplete-showcase .gallery-card-preview {
  min-height: 238px;
}
.autocomplete-preview {
  width: 215px;
  display: grid;
  gap: 8px;
  text-align: start;
  color: #373434;
}
.autocomplete-preview > span {
  border: 2px solid #373434;
  border-radius: 8px;
  padding: 10px 12px;
  background: #fff;
  box-shadow: 0 3px 0 #1d1b1b;
  font-size: 12px;
}
.autocomplete-preview > span:last-child {
  padding: 5px;
  display: grid;
  gap: 3px;
}
.autocomplete-preview i {
  padding: 7px;
  border-radius: 4px;
  font-style: normal;
  font-size: 11px;
}
.autocomplete-preview i:first-child {
  background: #f0eeee;
}
@keyframes autocomplete-reveal {
  from {
    opacity: 0;
    transform: translateY(-5px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (pointer: coarse) {
  .autocomplete-action {
    width: 44px;
    min-height: 40px;
  }
}
@media (max-width: 600px) {
  .autocomplete-control input {
    font-size: 16px;
  }
  .autocomplete-key-hint {
    display: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .autocomplete-control,
  .autocomplete-action,
  .autocomplete-trigger svg,
  .autocomplete-option,
  .autocomplete-option svg {
    transition: none;
  }
  .autocomplete-popup {
    animation: none;
  }
}

