.duoop-menu {
  position: relative;
  display: inline-block;
  color: #373434;
}
.duoop-menu__trigger {
  min-height: 44px;
  padding: 0 14px;
  border: 2px solid #373434;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 0 #1d1b1b;
  color: inherit;
  font: 600 13px inherit;
  cursor: pointer;
  transition:
    transform 100ms ease,
    box-shadow 120ms ease,
    background 150ms ease;
}
.duoop-menu__trigger:hover {
  background: #f4f2f2;
}
.duoop-menu__trigger:active,
.duoop-menu__trigger[aria-expanded='true'] {
  transform: translateY(2px);
  box-shadow: 0 1px 0 #1d1b1b;
}
.duoop-menu__trigger:focus-visible,
.duoop-menu__item:focus-visible {
  outline: none;
}
.duoop-menu__position {
  position: absolute;
  z-index: 35;
  min-width: 230px;
}
.duoop-menu__position--bottom-start {
  inset-block-start: calc(100% + 8px);
  inset-inline-start: 0;
}
.duoop-menu__position--bottom-end {
  inset-block-start: calc(100% + 8px);
  inset-inline-end: 0;
}
.duoop-menu__position--top-start {
  inset-block-end: calc(100% + 8px);
  inset-inline-start: 0;
}
.duoop-menu__position--top-end {
  inset-block-end: calc(100% + 8px);
  inset-inline-end: 0;
}
.duoop-menu__popup,
.duoop-menu__subpopup {
  padding: 7px;
  border: 2px solid #373434;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 5px 0 #1d1b1b;
  animation: menu-open 170ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.duoop-menu__item {
  width: 100%;
  min-height: 42px;
  padding: 8px 10px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  text-decoration: none;
  font: inherit;
  cursor: pointer;
}
.duoop-menu__item:hover,
.duoop-menu__item:focus-visible {
  background: #f0eeee;
}
.duoop-menu__item[aria-disabled='true'] {
  opacity: 0.38;
  cursor: not-allowed;
}
.duoop-menu__item[data-destructive] {
  color: #a51d2d;
}
.duoop-menu__mark {
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  flex: none;
}
.duoop-menu__mark svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.duoop-menu__copy {
  display: grid;
  gap: 2px;
  min-width: 0;
  flex: 1;
}
.duoop-menu__copy strong {
  font-size: 12px;
  font-weight: 600;
}
.duoop-menu__copy small {
  font-size: 10px;
  line-height: 1.35;
  color: #686565;
}
.duoop-menu__item kbd {
  font:
    10px Consolas,
    monospace;
  color: #686565;
}
.duoop-menu__label {
  padding: 9px 10px 5px;
  color: #686565;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.duoop-menu__separator {
  height: 1px;
  background: #dedada;
  margin: 6px;
}
.duoop-menu__submenu {
  position: relative;
}
.duoop-menu__subpopup {
  position: absolute;
  z-index: 1;
  inset-inline-start: calc(100% + 6px);
  inset-block-start: -7px;
  min-width: 210px;
}
.duoop-menu__popup {
  max-height: min(360px, 70vh);
  overflow: auto;
  overscroll-behavior: contain;
}
@keyframes menu-open {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-menu__trigger,
  .duoop-menu__popup,
  .duoop-menu__subpopup {
    animation: none;
    transition: none;
  }
}

