import React, { useState } from 'react';
import { Button } from '../Button/Button';
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../Dialog/Dialog';
import { Menu, MenuItem, MenuLabel, MenuSeparator, MenuSubmenu } from './Menu';
const icon = (name) => (
  <svg viewBox="0 0 20 20" aria-hidden="true">
    {name === 'edit' ? (
      <path d="m4 14 9-9 2 2-9 9H4z" />
    ) : name === 'copy' ? (
      <>
        <rect x="6" y="6" width="10" height="10" rx="2" />
        <path d="M4 13V5a1 1 0 0 1 1-1h8" />
      </>
    ) : (
      <path d="M4 5h12M6 5l1 11h6l1-11M8 5V3h4v2" />
    )}
  </svg>
);
function Items({ example, onDialog }) {
  const [checked, setChecked] = useState(true);
  const [radio, setRadio] = useState('edit');
  const long =
    example === 'Long scrollable menu'
      ? Array.from({ length: 14 }, (_, i) => (
          <MenuItem key={i}>Command {i + 1}</MenuItem>
        ))
      : null;
  if (long) return long;
  return (
    <>
      {example === 'Groups and separators' && <MenuLabel>Document</MenuLabel>}
      <MenuItem
        icon={example !== 'Without icons' && icon('edit')}
        shortcut={example === 'With shortcuts' ? '⌘E' : undefined}
        description={
          example === 'With descriptions'
            ? 'Change the title and summary.'
            : undefined
        }
        disabled={example === 'Disabled items'}
      >
        Edit document
      </MenuItem>
      <MenuItem
        icon={example !== 'Without icons' && icon('copy')}
        shortcut={example === 'With shortcuts' ? '⌘D' : undefined}
        href={example === 'Links' ? '#duplicate' : undefined}
      >
        Duplicate
      </MenuItem>
      {example === 'Groups and separators' && (
        <>
          <MenuSeparator />
          <MenuLabel>Preferences</MenuLabel>
        </>
      )}
      {example === 'Checkbox items' && (
        <MenuItem
          role="menuitemcheckbox"
          checked={checked}
          keepOpen
          onSelect={() => setChecked((x) => !x)}
        >
          Show comments
        </MenuItem>
      )}
      {example === 'Switch items' && (
        <MenuItem
          role="menuitemcheckbox"
          checked={checked}
          keepOpen
          onSelect={() => setChecked((x) => !x)}
        >
          Live updates
        </MenuItem>
      )}
      {example === 'Radio group' &&
        ['edit', 'view'].map((x) => (
          <MenuItem
            key={x}
            role="menuitemradio"
            checked={radio === x}
            keepOpen
            onSelect={() => setRadio(x)}
          >
            {x === 'edit' ? 'Can edit' : 'Can view'}
          </MenuItem>
        ))}
      {['Nested menu', 'Deep nested menu'].includes(example) && (
        <MenuSubmenu label="Move to">
          <MenuItem>Archive</MenuItem>
          <MenuSubmenu label="Workspace">
            <MenuItem>Design systems</MenuItem>
            <MenuItem>Research</MenuItem>
          </MenuSubmenu>
        </MenuSubmenu>
      )}
      {example === 'Open a Dialog' && (
        <MenuItem onSelect={onDialog}>Share settings…</MenuItem>
      )}
      <MenuSeparator />
      <MenuItem icon={icon('delete')} destructive={example === 'Destructive action'}>
        {example === 'Destructive action' ? 'Delete document' : 'Archive document'}
      </MenuItem>
    </>
  );
}
export const menuExamples = [
  ['Default', 'Basics'],
  ['With icons', 'Content'],
  ['Without icons', 'Content'],
  ['With shortcuts', 'Content'],
  ['With descriptions', 'Content'],
  ['Disabled items', 'States'],
  ['Destructive action', 'States'],
  ['Checkbox items', 'Selection'],
  ['Switch items', 'Selection'],
  ['Radio group', 'Selection'],
  ['Links', 'Content'],
  ['Groups and separators', 'Structure'],
  ['Nested menu', 'Hierarchy'],
  ['Deep nested menu', 'Hierarchy'],
  ['Open on hover', 'Behavior'],
  ['Keep open on click', 'Behavior'],
  ['Icon-only trigger', 'Triggers'],
  ['Open a Dialog', 'Integration'],
  ['Long scrollable menu', 'Structure'],
  ['Top end placement', 'Placement'],
];
export function MenuDemo({ example = 'Default' }) {
  const [dialog, setDialog] = useState(false);
  const trigger =
    example === 'Icon-only trigger' ? (
      <span aria-label="More actions">•••</span>
    ) : (
      'Actions'
    );
  return (
    <>
      <Menu
        trigger={trigger}
        openOnHover={example === 'Open on hover'}
        placement={example === 'Top end placement' ? 'top-end' : 'bottom-start'}
        label={`${example} actions`}
      >
        <Items example={example} onDialog={() => setDialog(true)} />
      </Menu>
      {example === 'Open a Dialog' && (
        <Dialog open={dialog} onOpenChange={setDialog}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Share settings</DialogTitle>
              <DialogDescription>
                Choose who can open this workspace.
              </DialogDescription>
            </DialogHeader>
            <DialogBody>
              Dialog focus is independent from the menu that launched it.
            </DialogBody>
            <DialogFooter>
              <Button onClick={() => setDialog(false)}>Done</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </>
  );
}

