import React, { useId, useRef, useState } from 'react';
import { Button } from '../Button/Button';
import { ExperienceIcon } from '../Feedback/ExperienceIcon';
import '../Feedback/Feedback.css';
import './Stepper.css';

export const stepStates = {
  upcoming: 'Upcoming',
  current: 'In progress',
  complete: 'Complete',
  skipped: 'Skipped',
  error: 'Needs attention',
  loading: 'Validating…',
  blocked: 'Prerequisite required',
  disabled: 'Disabled',
};
const resolved = (state) => ['complete', 'skipped'].includes(state);
export function getStepState(item, index, currentIndex) {
  return (
    item.state ||
    (index < currentIndex
      ? 'complete'
      : index === currentIndex
        ? 'current'
        : 'upcoming')
  );
}

/** Controlled navigation. Validation and conditional item inclusion belong to the caller. */
export function Stepper({
  items,
  value,
  onValueChange,
  label = 'Setup progress',
  orientation = 'horizontal',
  presentation = 'standard',
  indicator = 'number',
  labels = 'below',
  connector = 'continuous',
  progress = 0,
  linear = true,
  allowBack = true,
  content = 'none',
  mobile = 'vertical',
  overflow = 'scroll',
  size = 'md',
  formatSummary = (step, total) => `Step ${step} of ${total}`,
  className = '',
  ...props
}) {
  const id = useId();
  const root = useRef(null);
  const [expanded, setExpanded] = useState(false);
  const currentIndex = Math.max(
    0,
    items.findIndex((item) => item.id === value),
  );
  const current = items[currentIndex];
  const interactive = Boolean(onValueChange);
  const states = items.map((item, index) => getStepState(item, index, currentIndex));
  function canVisit(index) {
    if (!items[index] || ['blocked', 'disabled', 'loading'].includes(states[index]))
      return false;
    if (!allowBack && index < currentIndex) return false;
    return (
      !linear || index <= currentIndex || states.slice(0, index).every(resolved)
    );
  }
  function keys(event) {
    if (
      !['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(
        event.key,
      )
    )
      return;
    const buttons = [
      ...event.currentTarget.querySelectorAll('button[data-step]:not(:disabled)'),
    ];
    const active = buttons.indexOf(document.activeElement);
    if (active < 0) return;
    const rtl = getComputedStyle(root.current).direction === 'rtl';
    const forward = ['ArrowDown', rtl ? 'ArrowLeft' : 'ArrowRight'].includes(
      event.key,
    );
    const next =
      event.key === 'Home'
        ? 0
        : event.key === 'End'
          ? buttons.length - 1
          : Math.max(0, Math.min(buttons.length - 1, active + (forward ? 1 : -1)));
    event.preventDefault();
    buttons[next]?.focus();
  }
  const visible = items
    .map((_, i) => i)
    .filter(
      (i) =>
        overflow !== 'condensed' ||
        expanded ||
        items.length <= 5 ||
        i === 0 ||
        i === items.length - 1 ||
        Math.abs(i - currentIndex) <= 1,
    );
  const fraction = Number.isFinite(progress)
    ? Math.max(0, Math.min(1, progress))
    : 0;
  function expandAt(index) {
    setExpanded(true);
    requestAnimationFrame(() => {
      const controls = root.current?.querySelectorAll('button[data-step]') || [];
      const target = [...controls].find(
        (control) => control.dataset.step === items[index].id && !control.disabled,
      );
      const fallback = [...controls].find(
        (control) =>
          control.getAttribute('aria-current') === 'step' && !control.disabled,
      );
      (target || fallback)?.focus();
    });
  }
  if (!current)
    return (
      <p className="stepper-empty" role="status">
        No steps available.
      </p>
    );
  return (
    <div
      {...props}
      ref={root}
      className={`duoop-stepper ${className}`}
      data-orientation={orientation}
      data-presentation={presentation}
      data-indicator={indicator}
      data-labels={labels}
      data-connector={connector}
      data-mobile={mobile}
      data-overflow={overflow}
      data-size={size}
    >
      <div className="stepper-mobile-summary">
        <span className="stepper-marker" aria-hidden="true">
          {currentIndex + 1}
        </span>
        <div>
          <small>{formatSummary(currentIndex + 1, items.length)}</small>
          <strong>{current.title}</strong>
        </div>
        {interactive && (
          <div className="stepper-summary-actions">
            <Button
              variant="outline"
              iconPosition="only"
              icon={<span aria-hidden="true">−</span>}
              aria-label="Previous step"
              disabled={!canVisit(currentIndex - 1)}
              onClick={() => onValueChange(items[currentIndex - 1].id)}
            />
            <Button
              variant="outline"
              iconPosition="only"
              icon={<ExperienceIcon name="arrow" />}
              aria-label="Next step"
              disabled={!canVisit(currentIndex + 1)}
              onClick={() => onValueChange(items[currentIndex + 1].id)}
            />
          </div>
        )}
      </div>
      <nav aria-label={label} className="stepper-navigation">
        <ol className="stepper-list" onKeyDown={keys}>
          {visible.map((index, position) => {
            const item = items[index];
            const state = states[index];
            const stateLabel = item.stateLabel || stepStates[state];
            const active = index === currentIndex;
            const Control = interactive ? 'button' : 'div';
            const gap = position > 0 && index - visible[position - 1] > 1;
            const mark =
              state === 'complete' ? (
                <ExperienceIcon name="success" />
              ) : state === 'skipped' ? (
                <ExperienceIcon name="minus" />
              ) : state === 'error' ? (
                <ExperienceIcon name="error" />
              ) : state === 'loading' ? (
                <ExperienceIcon name="loading" />
              ) : ['blocked', 'disabled'].includes(state) ? (
                <ExperienceIcon name="lock" />
              ) : indicator === 'icon' ? (
                item.icon || <ExperienceIcon name="file" />
              ) : indicator === 'dot' ? (
                <span className="stepper-dot" />
              ) : (
                index + 1
              );
            return (
              <React.Fragment key={item.id}>
                {gap && (
                  <li className="stepper-gap">
                    <span className="stepper-connector" aria-hidden="true">
                      <i style={{ '--step-progress': 0 }} />
                    </span>
                    <Button
                      variant="outline"
                      size="sm"
                      iconPosition="only"
                      icon={<ExperienceIcon name="more" />}
                      aria-label={`Show ${index - visible[position - 1] - 1} hidden steps`}
                      onClick={() => expandAt(visible[position - 1] + 1)}
                    />
                    <small aria-hidden="true">
                      {index - visible[position - 1] - 1} hidden
                    </small>
                  </li>
                )}
                <li className="stepper-item" data-state={state} data-active={active}>
                  {position < visible.length - 1 && (
                    <span className="stepper-connector" aria-hidden="true">
                      <i
                        style={{
                          '--step-progress': resolved(state)
                            ? 1
                            : active
                              ? fraction
                              : 0,
                        }}
                      />
                    </span>
                  )}
                  <Control
                    {...(interactive
                      ? {
                          type: 'button',
                          disabled: !canVisit(index),
                          onClick: () => onValueChange(item.id),
                          'data-step': item.id,
                        }
                      : {})}
                    className="stepper-control"
                    aria-current={active ? 'step' : undefined}
                    aria-controls={
                      content === 'none'
                        ? undefined
                        : `${id}-panel-${content === 'panel' ? 'active' : item.id}`
                    }
                    aria-label={
                      interactive
                        ? `${index + 1}. ${item.title}. ${stateLabel}${item.optional ? '. Optional' : ''}`
                        : undefined
                    }
                  >
                    <span className="stepper-marker" key={state} aria-hidden="true">
                      {mark}
                    </span>
                    <span className="stepper-copy">
                      <strong>{item.title}</strong>
                      {presentation === 'detailed' && item.description && (
                        <span>{item.description}</span>
                      )}
                      <small>
                        {item.optional ? 'Optional · ' : ''}
                        {stateLabel}
                      </small>
                    </span>
                  </Control>
                  {content === 'inline' && (
                    <div
                      id={`${id}-panel-${item.id}`}
                      hidden={!active}
                      className="stepper-inline-panel"
                    >
                      {active && item.content}
                    </div>
                  )}
                </li>
              </React.Fragment>
            );
          })}
        </ol>
      </nav>
      {content === 'panel' && (
        <section
          className="stepper-panel"
          id={`${id}-panel-active`}
          aria-label={current.title}
        >
          <div key={current.id}>{current.content}</div>
        </section>
      )}
      <span className="duoop-sr-only" role="status">
        {formatSummary(currentIndex + 1, items.length)}. {current.title}.{' '}
        {current.stateLabel || stepStates[states[currentIndex]]}
      </span>
    </div>
  );
}

sources.ffcbbf7dd24ddf283d264ff35471e6bf79666d50:
.duoop-stepper {
  --step-mark: 40px;
  --step-ink: var(--feedback-ink, #373434);
  --step-face: var(--feedback-face, #fff);
  --step-edge: var(--feedback-edge, #1d1b1b);
  --step-soft: var(--feedback-soft, #f0eeee);
  --step-muted: var(--feedback-muted, #686565);
  width: 100%;
  min-width: 0;
  color: var(--step-ink);
  container-type: inline-size;
}
.duoop-stepper[data-size='sm'] {
  --step-mark: 32px;
}
.duoop-stepper[data-size='lg'] {
  --step-mark: 48px;
}
.stepper-list {
  list-style: none;
  display: flex;
  padding: 4px 2px 10px;
  margin: 0;
  gap: 0;
}
.stepper-item {
  position: relative;
  flex: 1 0 112px;
  min-width: 112px;
}
.stepper-control {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 0 8px;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: center;
  min-height: 44px;
  border-radius: 8px;
}
button.stepper-control {
  cursor: pointer;
}
.stepper-marker {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--step-mark);
  height: var(--step-mark);
  flex: none;
  border: 2px solid var(--step-edge);
  border-radius: 10px;
  background: var(--step-face);
  box-shadow: 0 3px 0 var(--step-edge);
  font-size: 14px;
  font-weight: 700;
  transition:
    transform 220ms cubic-bezier(0.2, 1.6, 0.4, 1),
    box-shadow 220ms cubic-bezier(0.2, 1.6, 0.4, 1),
    background-color 160ms ease,
    color 160ms ease;
}
.stepper-marker svg {
  width: 21px;
  height: 21px;
}
.stepper-copy {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  overflow-wrap: anywhere;
}
.stepper-copy strong {
  font-size: 13px;
  line-height: 1.5;
  font-weight: 650;
}
.stepper-copy > span {
  color: var(--step-muted);
  font-size: 12px;
  line-height: 1.65;
}
.stepper-copy small {
  color: var(--step-muted);
  font-size: 11px;
  line-height: 1.6;
}
.stepper-item[data-active='true'] .stepper-marker {
  background: var(--step-ink);
  color: var(--step-face);
  animation: stepper-arrive 300ms cubic-bezier(0.2, 1.6, 0.3, 1);
}
.stepper-item[data-state='complete'] .stepper-marker {
  background: var(--feedback-success-soft, #edf5ef);
  color: var(--feedback-success, #356247);
  border-color: currentColor;
  box-shadow: 0 3px 0 currentColor;
}
.stepper-item[data-state='complete'] {
  --step-edge: var(--feedback-success, #356247);
}
.stepper-item[data-state='error'] {
  --step-edge: var(--feedback-error, #a51d2d);
}
.stepper-item[data-state='error'] .stepper-marker {
  background: var(--feedback-error-soft, #fff2f3);
  color: var(--feedback-error, #a51d2d);
  border-color: currentColor;
  box-shadow: 0 3px 0 currentColor;
  animation: duoop-error 240ms ease-out;
}
.stepper-item[data-state='error'] .stepper-copy small {
  color: var(--feedback-error, #a51d2d);
}
.stepper-item[data-state='skipped'] .stepper-marker {
  border-style: solid;
  background: var(--step-soft);
}
.stepper-item[data-state='disabled'] .stepper-control,
.stepper-item[data-state='blocked'] .stepper-control {
  color: var(--step-muted);
}
.stepper-control:disabled {
  opacity: 1;
  cursor: not-allowed;
}
.stepper-control:focus-visible {
  outline: none;
}
.stepper-control:focus-visible .stepper-marker {
  outline: none;
  border-style: dashed;
}
.stepper-connector {
  position: absolute;
  z-index: 0;
  top: calc(var(--step-mark) / 2 - 2px);
  inset-inline-start: 50%;
  width: 100%;
  height: 6px;
  border-block: 1px solid var(--step-edge);
  background: var(--step-soft);
  pointer-events: none;
}
.stepper-connector i {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--step-ink);
  transform: scaleX(var(--step-progress));
  transform-origin: left;
  transition: transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.duoop-stepper:dir(rtl) .stepper-connector i {
  transform-origin: right;
}
.duoop-stepper[data-connector='segments'] .stepper-connector {
  inset-inline-start: calc(50% + var(--step-mark) / 2 + 8px);
  width: calc(100% - var(--step-mark) - 16px);
  border: 1px solid var(--step-edge);
  border-radius: 3px;
  overflow: hidden;
}
.duoop-stepper[data-connector='none'] .stepper-connector {
  display: none;
}
.stepper-dot {
  width: 9px;
  height: 9px;
  background: currentColor;
  border-radius: 2px;
  transform: rotate(45deg);
}
.duoop-stepper[data-presentation='compact'] .stepper-copy {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}
.duoop-stepper[data-labels='beside'] .stepper-item {
  flex-basis: 220px;
  min-width: 220px;
  display: flex;
  gap: 20px;
  align-items: flex-start;
}
.duoop-stepper[data-labels='beside'] .stepper-control {
  flex-direction: row;
  align-items: center;
  text-align: start;
  width: auto;
  flex: 0 1 auto;
  padding: 0;
  order: 0;
}
.duoop-stepper[data-labels='beside'] .stepper-copy {
  background: transparent;
  padding: 0;
}
.duoop-stepper[data-labels='beside'] .stepper-connector {
  position: relative;
  inset-inline-start: auto;
  flex: 1;
  min-width: 28px;
  width: auto;
  margin-inline-end: 16px;
  order: 1;
  border: 1px solid var(--step-edge);
  border-radius: 3px;
}
.duoop-stepper[data-orientation='vertical'] .stepper-list {
  flex-direction: column;
}
.duoop-stepper[data-orientation='vertical'] .stepper-item {
  display: block;
  flex: auto;
  min-width: 0;
}
.duoop-stepper[data-orientation='vertical'] .stepper-control {
  flex-direction: row;
  align-items: flex-start;
  text-align: start;
  padding: 0 0 28px;
}
.duoop-stepper[data-orientation='vertical'] .stepper-connector {
  position: absolute;
  min-width: 0;
  top: calc(var(--step-mark) / 2);
  inset-inline-start: calc(var(--step-mark) / 2 - 3px);
  width: 6px;
  height: 100%;
  border-block: 0;
  border-inline: 1px solid var(--step-edge);
}
.duoop-stepper[data-orientation='vertical'] .stepper-connector i {
  transform: scaleY(var(--step-progress));
  transform-origin: top;
}
.duoop-stepper[data-orientation='vertical']
  .stepper-item:last-child
  .stepper-control {
  padding-bottom: 0;
}
.stepper-inline-panel {
  position: relative;
  margin-inline-start: calc(var(--step-mark) + 14px);
  padding-block: 16px 32px;
}
.stepper-item:has(> .stepper-inline-panel:not([hidden])) > .stepper-control {
  padding-bottom: 0;
}
.stepper-panel {
  margin-top: 24px;
}
.stepper-panel > div,
.stepper-inline-panel > * {
  animation: stepper-panel-in 240ms ease-out;
}
.stepper-gap {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  gap: 14px;
  flex: 1 0 112px;
  min-width: 112px;
}
.stepper-gap .duoop-button {
  position: relative;
  z-index: 1;
  width: var(--step-mark);
  min-height: var(--step-mark);
  height: var(--step-mark);
  padding: 8px;
}
.stepper-gap .duoop-button-icon svg {
  width: 22px;
  height: 22px;
}
.stepper-gap > small {
  color: var(--step-muted);
  font-size: 11px;
  line-height: 1.6;
}
.stepper-navigation {
  overflow: auto;
  padding-bottom: 6px;
  scrollbar-width: thin;
}
.stepper-mobile-summary {
  display: none;
  align-items: center;
  gap: 16px;
}
.stepper-mobile-summary > div {
  min-width: 0;
}
.stepper-mobile-summary small,
.stepper-mobile-summary strong {
  display: block;
  overflow-wrap: anywhere;
}
.stepper-mobile-summary small {
  font-size: 11px;
  color: var(--step-muted);
  margin-bottom: 6px;
}
.stepper-mobile-summary strong {
  font-size: 14px;
}
.stepper-summary-actions {
  display: flex;
  gap: 8px;
  margin-inline-start: auto;
}
.stepper-empty {
  margin: 0;
  font-size: 13px;
}
.stepper-state-reference .stepper-marker,
.stepper-state-reference .stepper-marker * {
  animation: none;
}
@media (hover: hover) {
  button.stepper-control:hover:not(:disabled) .stepper-marker {
    transform: translateY(-2px);
    box-shadow: 0 5px 0 var(--step-edge);
  }
}
button.stepper-control:active:not(:disabled) .stepper-marker {
  transform: translateY(3px);
  box-shadow: none;
  transition-duration: 80ms;
}
@keyframes stepper-arrive {
  0% {
    transform: translateY(3px) scale(0.92);
  }
  65% {
    transform: translateY(-2px) scale(1.06);
  }
  to {
    transform: none;
  }
}
@keyframes stepper-panel-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@container (max-width:460px) {
  .duoop-stepper[data-mobile='summary'] .stepper-navigation {
    display: none;
  }
  .duoop-stepper[data-mobile='summary'] .stepper-mobile-summary {
    display: flex;
  }
  .duoop-stepper[data-mobile='vertical'] .stepper-list {
    flex-direction: column;
  }
  .duoop-stepper[data-mobile='vertical'] .stepper-item {
    display: block;
    flex: auto;
    min-width: 0;
  }
  .duoop-stepper[data-mobile='vertical'] .stepper-control {
    flex-direction: row;
    text-align: start;
    align-items: flex-start;
    padding: 0 0 24px;
  }
  .duoop-stepper[data-mobile='vertical'] .stepper-connector {
    position: absolute;
    min-width: 0;
    top: calc(var(--step-mark) / 2);
    inset-inline-start: calc(var(--step-mark) / 2 - 3px);
    width: 6px;
    height: 100%;
    border-block: 0;
    border-inline: 1px solid var(--step-edge);
  }
  .duoop-stepper[data-mobile='vertical'] .stepper-connector i {
    transform: scaleY(var(--step-progress));
    transform-origin: top;
  }
  .duoop-stepper[data-mobile='vertical'] .stepper-item:last-child .stepper-control {
    padding-bottom: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .stepper-marker,
  .stepper-marker *,
  .stepper-connector i,
  .stepper-panel > div,
  .stepper-inline-panel > * {
    animation: none;
    transition: none;
  }
  button.stepper-control:hover:not(:disabled) .stepper-marker,
  button.stepper-control:active:not(:disabled) .stepper-marker {
    transform: none;
  }
}

.stepper-progress-control {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 12px;
}
.stepper-progress-control > input[type='range'] {
  display: block;
  margin: 0;
  width: 128px;
  max-width: 100%;
  accent-color: var(--step-ink, #373434);
}

