.duoop-accordion {
  --acc-edge: #373434;
  --acc-face: #fff;
  --acc-muted: #686565;
  --acc-soft: #f0eeee;
  --acc-shadow: #1d1b1b;
  --acc-inset: 20px;
  width: min(100%, 620px);
  color: var(--acc-edge);
  text-align: start;
}
.duoop-accordion__item {
  background: var(--acc-face);
  border: 2px solid var(--acc-edge);
  border-radius: 10px;
  box-shadow: 0 3px 0 var(--acc-shadow);
  transition:
    box-shadow 180ms ease,
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.duoop-accordion__item + .duoop-accordion__item {
  margin-top: 12px;
}
.duoop-accordion__heading {
  margin: 0;
  font: inherit;
}
.duoop-accordion__trigger {
  width: 100%;
  min-height: 64px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px var(--acc-inset);
  text-align: start;
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.45;
  cursor: pointer;
  transition:
    background 160ms ease,
    color 160ms ease;
}
.duoop-accordion__trigger:hover:not(:disabled) {
  background: var(--acc-soft);
}
.duoop-accordion__trigger:focus-visible {
  outline: none;
}
.duoop-accordion__trigger[aria-expanded='true'] {
  border-end-start-radius: 0;
  border-end-end-radius: 0;
}
.duoop-accordion__copy {
  display: grid;
  gap: 6px;
  min-width: 0;
  flex: 1;
  overflow-wrap: anywhere;
}
.duoop-accordion__copy small {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.6;
  color: var(--acc-muted);
}
.duoop-accordion__meta {
  flex: none;
  font-size: 11px;
  border: 1px solid var(--acc-edge);
  border-radius: 5px;
  padding: 3px 7px;
  background: var(--acc-face);
  color: var(--acc-edge);
}
.duoop-accordion__meta:has(.duoop-badge) {
  border: 0;
  padding: 0;
  background: transparent;
}
.duoop-accordion__meta .duoop-badge {
  white-space: nowrap;
}
.duoop-accordion__leading,
.duoop-accordion__chevron {
  display: grid;
  place-items: center;
  flex: none;
}
.duoop-accordion__leading svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.duoop-accordion__chevron {
  width: 28px;
  height: 28px;
  border: 2px solid var(--acc-edge);
  border-radius: 6px;
  background: var(--acc-face);
  color: var(--acc-edge);
  box-shadow: 0 2px 0 var(--acc-shadow);
  transition:
    transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 160ms ease,
    background 160ms ease,
    color 160ms ease;
}
.duoop-accordion__chevron svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 280ms cubic-bezier(0.22, 1.3, 0.36, 1);
}
.duoop-accordion__trigger:hover:not(:disabled) .duoop-accordion__chevron {
  transform: translateY(-2px);
  box-shadow: 0 4px 0 var(--acc-shadow);
}
.duoop-accordion__trigger:active:not(:disabled) .duoop-accordion__chevron {
  transform: translateY(2px);
  box-shadow: 0 0 0 var(--acc-shadow);
}
.duoop-accordion__trigger[aria-expanded='true'] .duoop-accordion__chevron {
  background: var(--acc-edge);
  color: var(--acc-face);
}
.duoop-accordion__trigger[aria-expanded='true'] .duoop-accordion__chevron svg {
  transform: rotate(180deg);
}
.duoop-accordion__region {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  visibility: hidden;
  transition:
    grid-template-rows 300ms cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 180ms ease,
    visibility 300ms;
}
.duoop-accordion__region[data-open] {
  grid-template-rows: 1fr;
  opacity: 1;
  visibility: visible;
}
.duoop-accordion__clip {
  min-height: 0;
  overflow: hidden;
}
.duoop-accordion__content {
  margin-inline: var(--acc-inset);
  padding: 4px 0 22px;
  color: var(--acc-muted);
  font-size: 13px;
  line-height: 1.8;
  overflow-wrap: anywhere;
  transform: translateY(-6px);
  transition: transform 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.duoop-accordion__region[data-open]
  > .duoop-accordion__clip
  > .duoop-accordion__content {
  transform: translateY(0);
}
.duoop-accordion__content > :first-child {
  margin-top: 0;
}
.duoop-accordion__content > :last-child {
  margin-bottom: 0;
}
.duoop-accordion__item[data-disabled] {
  color: var(--acc-muted);
  box-shadow: none;
  border-style: solid;
}
.duoop-accordion__trigger:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}
.duoop-accordion--outline,
.duoop-accordion--contained {
  border: 2px solid var(--acc-edge);
  border-radius: 10px;
  box-shadow: 0 4px 0 var(--acc-shadow);
  background: var(--acc-face);
}
.duoop-accordion--outline > .duoop-accordion__item,
.duoop-accordion--contained > .duoop-accordion__item {
  border: 0;
  border-radius: 0;
  box-shadow: none;
  margin: 0;
}
.duoop-accordion--outline > .duoop-accordion__item + .duoop-accordion__item,
.duoop-accordion--contained > .duoop-accordion__item + .duoop-accordion__item {
  border-top: 2px solid var(--acc-edge);
}
.duoop-accordion--outline > .duoop-accordion__item:first-child,
.duoop-accordion--contained > .duoop-accordion__item:first-child {
  border-radius: 8px 8px 0 0;
}
.duoop-accordion--outline > .duoop-accordion__item:last-child,
.duoop-accordion--contained > .duoop-accordion__item:last-child {
  border-radius: 0 0 8px 8px;
}
.duoop-accordion--contained
  > .duoop-accordion__item
  > .duoop-accordion__heading
  > .duoop-accordion__trigger {
  background: var(--acc-soft);
  border-radius: inherit;
}
.duoop-accordion--contained
  > .duoop-accordion__item
  > .duoop-accordion__heading
  > .duoop-accordion__trigger[aria-expanded='true'] {
  background: var(--acc-edge);
  color: var(--acc-face);
}
.duoop-accordion--contained
  > .duoop-accordion__item
  > .duoop-accordion__heading
  > .duoop-accordion__trigger[aria-expanded='true']
  .duoop-accordion__copy
  small {
  color: #e1dcdc;
}
.duoop-accordion--contained
  > .duoop-accordion__item
  > .duoop-accordion__heading
  > .duoop-accordion__trigger[aria-expanded='true']
  > .duoop-accordion__chevron {
  background: var(--acc-face);
  color: var(--acc-edge);
}
.duoop-accordion--contained > .duoop-accordion__item:only-child {
  border-radius: 8px;
}
.duoop-accordion--contained > .duoop-accordion__item > .duoop-accordion__heading {
  border-radius: inherit;
}
.duoop-accordion--contained
  > .duoop-accordion__item
  > .duoop-accordion__region
  > .duoop-accordion__clip
  > .duoop-accordion__content {
  padding-top: 18px;
}
.duoop-accordion--ghost > .duoop-accordion__item {
  box-shadow: none;
  border: 0;
  border-bottom: 2px solid var(--acc-edge);
  border-radius: 0;
  margin: 0;
}
.duoop-accordion--sm {
  --acc-inset: 14px;
}
.duoop-accordion--sm
  > .duoop-accordion__item
  > .duoop-accordion__heading
  > .duoop-accordion__trigger {
  min-height: 48px;
  padding-block: 10px;
  font-size: 13px;
}
.duoop-accordion--lg {
  --acc-inset: 24px;
}
.duoop-accordion--lg
  > .duoop-accordion__item
  > .duoop-accordion__heading
  > .duoop-accordion__trigger {
  min-height: 76px;
  padding-block: 20px;
  font-size: 16px;
}
@media (prefers-reduced-motion: reduce) {
  .duoop-accordion__item,
  .duoop-accordion__trigger,
  .duoop-accordion__chevron,
  .duoop-accordion__chevron svg,
  .duoop-accordion__region,
  .duoop-accordion__content {
    transition: none;
  }
  .duoop-accordion__trigger .duoop-accordion__chevron,
  .duoop-accordion__content {
    transform: none;
  }
}

