import React, { useState } from 'react';
import { Badge } from '../Badge/Badge';
import { Input } from '../Forms/Input';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from './Accordion';
const notes = [
  [
    'overview',
    'What is included?',
    'The component includes keyboard navigation, controlled and uncontrolled state, and reduced-motion behavior.',
  ],
  [
    'billing',
    'How does billing work?',
    'Plans renew monthly. You can change or cancel before the next renewal date.',
  ],
  [
    'privacy',
    'Where is my data stored?',
    'Workspace data is encrypted in transit and at rest, with regional storage options.',
  ],
];
const icon = (
  <svg viewBox="0 0 24 24">
    <path d="M6 3h9l3 3v15H6zM15 3v4h4M9 11h6M9 15h6" />
  </svg>
);
function Set({ example, value, onValueChange }) {
  let data = notes,
    props = { defaultValue: 'overview' };
  if (example === 'Multiple')
    props = { type: 'multiple', defaultValue: ['overview', 'billing'] };
  if (example === 'Collapsible') props = { defaultValue: '' };
  if (example === 'One required open')
    props = { collapsible: false, defaultValue: 'overview' };
  if (example === 'Outline') props.variant = 'outline';
  if (example === 'Contained card') props.variant = 'contained';
  if (example === 'Ghost') props.variant = 'ghost';
  if (example === 'Compact') props.size = 'sm';
  if (example === 'Controlled') props = { value, onValueChange };
  if (example === 'Disabled item')
    data = notes.map((x, i) => (i === 1 ? [...x, true] : x));
  if (example === 'Description and badge') data = notes;
  if (example === 'Long content')
    data = [
      [
        'long',
        'A longer heading that wraps naturally without moving the action or clipping the disclosure icon',
        'Long-form disclosure remains readable. '.repeat(10),
      ],
    ];
  return (
    <Accordion {...props}>
      {data.map(([id, title, content, disabled], i) => (
        <AccordionItem key={id} value={id} disabled={disabled}>
          <AccordionTrigger
            icon={example === 'With icons' ? icon : undefined}
            description={
              example === 'Description and badge'
                ? 'Updated workspace guidance'
                : undefined
            }
            meta={
              example === 'Description and badge' && i === 0 ? (
                <Badge size="sm" appearance="outline" tone="info">
                  3 updates
                </Badge>
              ) : undefined
            }
          >
            {title}
          </AccordionTrigger>
          <AccordionContent>
            {example === 'Nested content' && i === 0 ? (
              <Accordion variant="outline" size="sm">
                <AccordionItem value="nested">
                  <AccordionTrigger>Nested detail</AccordionTrigger>
                  <AccordionContent>
                    Nested disclosure preserves its own state.
                  </AccordionContent>
                </AccordionItem>
              </Accordion>
            ) : example === 'Form content' && i === 0 ? (
              <Input aria-label="Project name" placeholder="Project name" />
            ) : (
              <p>{content}</p>
            )}
          </AccordionContent>
        </AccordionItem>
      ))}
    </Accordion>
  );
}
export const accordionExamples = [
  ['Default', 'Appearance'],
  ['Multiple', 'Behavior'],
  ['Collapsible', 'Behavior'],
  ['One required open', 'Behavior'],
  ['Controlled', 'State'],
  ['Disabled item', 'States'],
  ['With icons', 'Content'],
  ['Description and badge', 'Content'],
  ['Outline', 'Appearance'],
  ['Contained card', 'Appearance'],
  ['Ghost', 'Appearance'],
  ['Long content', 'Content'],
  ['Nested content', 'Content'],
  ['Form content', 'Content'],
  ['Compact', 'Density'],
];
export function AccordionDemo({ example = 'Default' }) {
  const [value, setValue] = useState('overview');
  return <Set example={example} value={value} onValueChange={setValue} />;
}

