sources.2dfb0f3e9fa3b1931a164f7d1ac27bcd1a0ef188:
import React from 'react';
import './BentoGrid.css';

/** Content order is also reading order. Spans collapse within narrow containers. */
export function BentoGrid({
  children,
  label = 'Bento grid',
  className = '',
  ...props
}) {
  return (
    <section {...props} aria-label={label} className={`duoop-bento ${className}`}>
      <div className="duoop-bento__grid">{children}</div>
    </section>
  );
}

export function BentoItem({
  children,
  span = 'single',
  tone = 'default',
  className = '',
  ...props
}) {
  return (
    <article
      {...props}
      className={`duoop-bento__item duoop-bento__item--${span} duoop-bento__item--${tone} ${className}`}
    >
      {children}
    </article>
  );
}

sources.c37c61b5e8b6b60d303a3662c2a48690fbb3c78b:
.duoop-bento {
  container-type: inline-size;
  width: 100%;
  color: var(--feedback-ink, #373434);
}
.duoop-bento__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}
.duoop-bento__item {
  min-width: 0;
  padding: 24px;
  border: 2px solid var(--feedback-edge, #1d1b1b);
  border-radius: 10px;
  background: var(--feedback-face, #fff);
  box-shadow: 0 4px 0 var(--feedback-edge, #1d1b1b);
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-wrap: anywhere;
  transition:
    transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.duoop-bento__item--soft {
  background: var(--feedback-soft, #f0eeee);
}
.duoop-bento__item--feature {
  grid-column: span 2;
  grid-row: span 2;
}
.duoop-bento__item--wide {
  grid-column: span 2;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.duoop-bento__item:focus-within {
  border-style: solid;
}
@media (hover: hover) {
  .duoop-bento__item:hover {
    transform: translateY(-3px);
    box-shadow: 0 7px 0 var(--feedback-edge, #1d1b1b);
  }
}
.bento-demo {
  width: 100%;
  min-width: 0;
}
.bento-demo[data-theme='dark'] {
  padding: 24px;
  border-radius: 12px;
  background: var(--feedback-face);
}
.bento-kicker {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--feedback-muted);
}
.bento-kicker svg {
  width: 22px;
  height: 22px;
  flex: none;
  color: var(--feedback-ink);
}
.duoop-bento__item h3 {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.6px;
  color: inherit;
}
.duoop-bento__item p {
  margin: 0;
  font-size: 13px;
  line-height: 1.75;
  color: var(--feedback-muted);
}
.bento-hero-copy {
  padding-top: 24px;
}
.bento-hero-copy h3 {
  font-size: clamp(30px, 5.6cqi, 54px);
  line-height: 1.08;
  letter-spacing: -2px;
  margin-bottom: 20px;
}
.bento-drawing {
  width: 100%;
  max-width: 440px;
  align-self: center;
  margin: auto 0;
  padding: 12px 0;
  flex: none;
}
.bento-drawing__layout {
  animation: bento-layout-in 280ms ease-out;
  transform-origin: center;
}
@keyframes bento-layout-in {
  from {
    opacity: 0.35;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.bento-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 11px;
  color: var(--feedback-muted);
}
.bento-metric {
  font-size: 52px;
  font-weight: 600;
  letter-spacing: -2px;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}
.bento-metric span {
  font-size: 20px;
  color: var(--feedback-muted);
  letter-spacing: -0.5px;
}
.bento-meter {
  display: flex;
  gap: 5px;
  margin-top: auto;
  padding-top: 8px;
}
.bento-meter i {
  flex: 1;
  height: 20px;
  border: 1px solid var(--feedback-edge);
  border-radius: 3px;
  background: var(--feedback-ink);
}
.bento-save {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-top: auto;
}
.bento-status {
  font-size: 11px;
  color: var(--feedback-muted);
  min-height: 18px;
}
.bento-bottom-copy {
  display: grid;
  gap: 12px;
}
.bento-formats {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  flex: none;
}
.bento-formats span {
  width: 52px;
  height: 40px;
  border: 2px solid var(--feedback-edge);
  border-radius: 5px;
  box-shadow: 0 3px 0 var(--feedback-edge);
  background: var(--feedback-soft);
}
.bento-formats span:nth-child(2) {
  width: 30px;
  height: 44px;
}
.bento-formats span:nth-child(3) {
  width: 22px;
  height: 34px;
}
.bento-playground {
  padding: 28px;
  margin-bottom: 48px;
  background: #fafbfc;
  border: 1px solid #e7e9ed;
  border-radius: 12px;
}
.bento-playground__heading {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 24px;
}
.bento-playground__heading > span:last-child {
  font-size: 11px;
  color: #646c78;
}
.bento-grid-showcase .gallery-card-preview {
  padding: 28px;
}
.bento-grid-showcase .gallery-card--wide {
  grid-column: 1 / -1;
}
.bento-mini {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  grid-template-rows: 48px 48px 36px;
  gap: 8px;
  width: 235px;
  color: #373434;
}
.bento-mini > span {
  border: 2px solid #373434;
  border-radius: 6px;
  box-shadow: 0 3px 0 #1d1b1b;
  background: white;
  padding: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.bento-mini > span:first-child {
  grid-row: span 2;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
  background: #f0eeee;
}
.bento-mini small {
  font-size: 7px;
  letter-spacing: 0.1em;
}
.bento-mini strong {
  font-size: 15px;
  line-height: 1.2;
  letter-spacing: -0.5px;
}
.bento-mini > span:last-child {
  grid-column: span 2;
  justify-content: space-between;
  font-size: 10px;
}
.bento-mini svg {
  width: 20px;
  height: 20px;
}
.bento-mini i {
  width: 10px;
  height: 18px;
  border: 1px solid #373434;
  background: #f0eeee;
  border-radius: 2px;
}
.bento-mini i:nth-child(2) {
  height: 26px;
}
@container (max-width:700px) {
  .duoop-bento__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .duoop-bento__item--feature {
    grid-row: auto;
  }
  .duoop-bento__item--wide {
    grid-column: span 1;
    flex-direction: column;
    align-items: flex-start;
  }
  .bento-hero-copy h3 {
    font-size: 42px;
  }
}
@container (max-width:440px) {
  .duoop-bento__grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }
  .duoop-bento__item {
    grid-column: auto;
    grid-row: auto;
    padding: 20px;
  }
  .bento-hero-copy h3 {
    font-size: 36px;
  }
  .bento-hero-copy {
    padding-top: 12px;
  }
}
@media (max-width: 600px) {
  .bento-playground,
  .bento-grid-showcase .gallery-card-preview {
    padding: 16px;
  }
  .bento-demo[data-theme='dark'] {
    padding: 12px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-bento__item {
    transition: none;
  }
  .duoop-bento__item:hover {
    transform: none;
    box-shadow: 0 4px 0 var(--feedback-edge, #1d1b1b);
  }
  .bento-drawing__layout {
    animation: none;
  }
}

