import React, { useEffect, useId, useRef, useState } from 'react';
import { Button } from '../Button/Button';
import '../Feedback/Feedback.css';
import './CardsCarousel.css';

const Arrow = ({ back = false }) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.8"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d={back ? 'M19 12H5m6-6-6 6 6 6' : 'M5 12h14m-6-6 6 6-6 6'} />
  </svg>
);

function CardImage({ src, alt = '', className = '' }) {
  const [failed, setFailed] = useState(false);
  return src && !failed ? (
    <img
      className={className}
      src={src}
      alt={alt}
      loading="lazy"
      onError={() => setFailed(true)}
    />
  ) : (
    <span className={`cards-carousel__image-fallback ${className}`}>
      Image unavailable
    </span>
  );
}

function StoryWindow({ src }) {
  const frame = useRef(null);
  const id = useId();
  const [bounds, setBounds] = useState({ width: 260, height: 224 });
  useEffect(() => {
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      if (width && height) setBounds({ width, height });
    });
    observer.observe(frame.current);
    return () => observer.disconnect();
  }, []);
  const { width, height } = bounds;
  const radius = (width - 2) / 2;
  const corner = 7;
  const base = height - 1;
  // A single circular arch, tangent to both sides; the photo and ink share it.
  const path = `M1 ${radius + 1} A${radius} ${radius} 0 0 1 ${width - 1} ${radius + 1} V${base - corner} Q${width - 1} ${base} ${width - 1 - corner} ${base} H${corner + 1} Q1 ${base} 1 ${base - corner} Z`;
  return (
    <svg ref={frame} className="cards-carousel__window" aria-hidden="true">
      <defs>
        <path id={`${id}-shape`} d={path} />
        <clipPath id={`${id}-clip`}>
          <use href={`#${id}-shape`} />
        </clipPath>
      </defs>
      <g clipPath={`url(#${id}-clip)`}>
        <foreignObject width={width} height={height}>
          <CardImage key={src} src={src} className="cards-carousel__image" />
        </foreignObject>
      </g>
      <use
        href={`#${id}-shape`}
        fill="none"
        stroke="var(--story-border)"
        strokeWidth="2"
      />
    </svg>
  );
}

/** A scroll-snap collection with native touch scrolling and modal card details. */
export function CardsCarousel({
  items = [],
  title = 'A little more to discover.',
  label = 'Featured stories',
  size = 'large',
  theme = 'light',
  className = '',
}) {
  const rail = useRef(null);
  const progress = useRef(null);
  const dialog = useRef(null);
  const headingId = useId();
  const detailId = useId();
  const detailHeading = useRef(null);
  const [selectedId, setSelectedId] = useState(null);
  const selected = items.find((item) => item.id === selectedId);
  const selectedIndex = items.findIndex((item) => item.id === selectedId);
  const [position, setPosition] = useState({ start: true, end: true });

  useEffect(() => {
    const node = rail.current;
    const measure = () => {
      const distance = node.scrollWidth - node.clientWidth;
      progress.current?.style.setProperty(
        '--collection-progress',
        String(
          distance > 0 ? Math.max(0, Math.min(1, node.scrollLeft / distance)) : 1,
        ),
      );
      const next = {
        start: node.scrollLeft <= 2,
        end: node.scrollLeft + node.clientWidth >= node.scrollWidth - 2,
      };
      setPosition((previous) =>
        previous.start === next.start && previous.end === next.end ? previous : next,
      );
    };
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    for (const child of node.children) observer.observe(child);
    node.addEventListener('scroll', measure, { passive: true });
    measure();
    return () => {
      observer.disconnect();
      node.removeEventListener('scroll', measure);
    };
  }, [items, size]);

  useEffect(() => {
    const node = dialog.current;
    if (!selected) {
      if (node.open) node.close();
      return;
    }
    if (!node.open) node.showModal();
    else detailHeading.current?.focus({ preventScroll: true });
    node.scrollTop = 0;
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = overflow;
    };
  }, [selected]);

  const close = () => {
    dialog.current.close();
    setSelectedId(null);
  };
  function move(direction) {
    const node = rail.current;
    const card = node.firstElementChild;
    if (!card) return;
    const step = card.offsetWidth + parseFloat(getComputedStyle(node).columnGap);
    node.scrollBy({
      left: direction * step,
      behavior: matchMedia('(prefers-reduced-motion: reduce)').matches
        ? 'instant'
        : 'smooth',
    });
  }
  function navigate(event) {
    if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    const buttons = [...rail.current.querySelectorAll('.cards-carousel__card')];
    if (!buttons.length) return;
    event.preventDefault();
    const current = buttons.indexOf(document.activeElement);
    const index =
      event.key === 'Home'
        ? 0
        : event.key === 'End'
          ? buttons.length - 1
          : Math.max(
              0,
              Math.min(
                buttons.length - 1,
                current + (event.key === 'ArrowRight' ? 1 : -1),
              ),
            );
    buttons[index].focus({ preventScroll: true });
    buttons[index].scrollIntoView({
      block: 'nearest',
      inline: 'nearest',
      behavior: 'instant',
    });
  }

  return (
    <section
      className={`cards-carousel feedback-surface ${className}`}
      data-size={size}
      data-theme={theme}
      aria-label={label}
      aria-roledescription="carousel"
    >
      <header className="cards-carousel__heading">
        <div>
          <span className="cards-carousel__eyebrow">
            THE COLLECTION / {String(items.length).padStart(2, '0')} STORIES
          </span>
          <h3 id={headingId}>{title}</h3>
        </div>
        <span className="cards-carousel__hint">
          A new perspective, one card away.
        </span>
      </header>
      <div
        className="cards-carousel__rail"
        ref={rail}
        onKeyDown={navigate}
        aria-labelledby={headingId}
      >
        {items.map((item, index) => (
          <button
            key={item.id}
            className="cards-carousel__card"
            type="button"
            aria-label={`Read ${item.title}`}
            aria-haspopup="dialog"
            onClick={() => setSelectedId(item.id)}
          >
            <span className="cards-carousel__copy">
              <span className="cards-carousel__eyebrow">{item.category}</span>
              <strong>{item.title}</strong>
            </span>
            <StoryWindow src={item.src} />
            <span className="cards-carousel__card-footer">
              <span>{String(index + 1).padStart(2, '0')} / Explore story</span>
              <span className="cards-carousel__plus" aria-hidden="true">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.8"
                >
                  <path d="M5 12h14M12 5v14" />
                </svg>
              </span>
            </span>
          </button>
        ))}
        {!items.length && (
          <p className="cards-carousel__empty">No stories to display.</p>
        )}
      </div>
      <footer className="cards-carousel__navigation">
        <span>
          Scroll to explore. Select a card to go deeper.
          <span
            ref={progress}
            className="cards-carousel__progress"
            aria-hidden="true"
          >
            <span />
          </span>
        </span>
        <div>
          <Button
            variant="outline"
            iconPosition="only"
            icon={<Arrow back />}
            aria-label="Previous cards"
            disabled={position.start}
            onClick={() => move(-1)}
          />
          <Button
            variant="outline"
            iconPosition="only"
            icon={<Arrow />}
            aria-label="Next cards"
            disabled={position.end}
            onClick={() => move(1)}
          />
        </div>
      </footer>
      <dialog
        ref={dialog}
        className="cards-carousel__dialog"
        aria-labelledby={detailId}
        onCancel={(event) => {
          event.preventDefault();
          event.stopPropagation();
          close();
        }}
        onClose={(event) => {
          event.stopPropagation();
          setSelectedId(null);
        }}
        onClick={(event) => {
          if (event.target === event.currentTarget) {
            const rect = event.currentTarget.getBoundingClientRect();
            if (
              event.clientX < rect.left ||
              event.clientX > rect.right ||
              event.clientY < rect.top ||
              event.clientY > rect.bottom
            )
              close();
          }
        }}
      >
        {selected && (
          <>
            <div className="cards-carousel__detail-toolbar">
              <span className="cards-carousel__eyebrow">
                The collection <span aria-hidden="true">/</span> Field notes
              </span>
              <Button
                variant="outline"
                iconPosition="only"
                aria-label="Close story"
                onClick={close}
                icon={
                  <svg
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.8"
                  >
                    <path d="m6 6 12 12M18 6 6 18" />
                  </svg>
                }
              />
            </div>
            <article className="cards-carousel__story" key={selected.id}>
              <header className="cards-carousel__detail-heading">
                <span className="cards-carousel__story-number" aria-hidden="true">
                  {String(selectedIndex + 1).padStart(2, '0')}
                </span>
                <div>
                  <span className="cards-carousel__eyebrow">
                    {selected.category}
                  </span>
                  <h2 ref={detailHeading} tabIndex={-1} id={detailId}>
                    {selected.title}
                  </h2>
                </div>
              </header>
              <figure className="cards-carousel__figure">
                <CardImage
                  key={selected.src}
                  src={selected.src}
                  alt={selected.alt}
                  className="cards-carousel__detail-image"
                />
                <figcaption>
                  <span>A new perspective, one card away.</span>
                  <span>
                    {String(selectedIndex + 1).padStart(2, '0')} /{' '}
                    {String(items.length).padStart(2, '0')}
                  </span>
                </figcaption>
              </figure>
              <div className="cards-carousel__detail-content">
                <div className="cards-carousel__prose">{selected.content}</div>
                {selected.takeaway && (
                  <aside className="cards-carousel__takeaway">
                    <svg
                      viewBox="0 0 32 32"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      aria-hidden="true"
                    >
                      <path d="M8 4h13l4 4v20H8zM20 4v5h5M12 14h9M12 19h6M12 24h4" />
                    </svg>
                    <span className="cards-carousel__eyebrow">Try this today</span>
                    <p>{selected.takeaway}</p>
                  </aside>
                )}
              </div>
            </article>
            <footer className="cards-carousel__detail-footer">
              <Button
                className="cards-carousel__return"
                variant="outline"
                onClick={close}
              >
                Back to collection
              </Button>
              <nav aria-label="Story navigation">
                <Button
                  variant="outline"
                  iconPosition="only"
                  icon={<Arrow back />}
                  aria-label="Previous story"
                  disabled={selectedIndex === 0}
                  onClick={() => setSelectedId(items[selectedIndex - 1].id)}
                />
                <span className="cards-carousel__story-position" role="status">
                  {String(selectedIndex + 1).padStart(2, '0')}{' '}
                  <span>/ {String(items.length).padStart(2, '0')}</span>
                </span>
                <Button
                  variant="outline"
                  iconPosition="only"
                  icon={<Arrow />}
                  aria-label="Next story"
                  disabled={selectedIndex === items.length - 1}
                  onClick={() => setSelectedId(items[selectedIndex + 1].id)}
                />
              </nav>
            </footer>
          </>
        )}
      </dialog>
    </section>
  );
}

sources.73d2086993d86e572c1251731988982f9258fb72:
.cards-carousel__rail::-webkit-scrollbar {
  display: none;
}
.cards-carousel {
  width: 100%;
  min-width: 0;
  background: var(--feedback-face);
  color: var(--feedback-ink);
  --story-border: var(--feedback-edge);
}
.cards-carousel__heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  padding: 32px 32px 24px;
}
.cards-carousel__eyebrow {
  display: block;
  font-size: 10px;
  line-height: 1.5;
  letter-spacing: 1.2px;
  font-weight: 600;
  text-transform: uppercase;
}
.cards-carousel__heading h3 {
  margin: 12px 0 0;
  max-width: 440px;
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1.12;
  font-weight: 600;
  letter-spacing: -1.2px;
  text-wrap: balance;
}
.cards-carousel__hint {
  max-width: 150px;
  font-size: 12px;
  color: var(--feedback-muted);
  line-height: 1.7;
}
.cards-carousel__rail {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 32px;
  padding: 32px 32px 48px;
  scrollbar-width: none;
  background: var(--feedback-soft);
  border-block: 1px solid var(--feedback-track);
}
.cards-carousel__card {
  position: relative;
  flex: 0 0 300px;
  min-width: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  text-align: start;
  font: inherit;
  color: inherit;
  background: var(--feedback-face);
  border: 2px solid var(--story-border);
  border-radius: 10px;
  box-shadow: 0 5px 0 var(--story-border);
  overflow: hidden;
  scroll-snap-align: start;
  cursor: pointer;
  transform: translateY(var(--card-rise, 0px));
  transition:
    transform 280ms cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 200ms ease-out;
}
.cards-carousel__card:nth-child(even) {
  --card-rise: 16px;
}
.cards-carousel__copy {
  display: block;
  min-height: 156px;
  padding: 24px;
}
.cards-carousel__copy strong {
  display: block;
  margin-top: 12px;
  font-size: 27px;
  font-weight: 800;
  line-height: 1.06;
  letter-spacing: -0.8px;
  text-transform: uppercase;
  text-wrap: balance;
  overflow-wrap: anywhere;
}
.cards-carousel__window {
  display: block;
  width: calc(100% - 36px);
  height: 224px;
  flex-shrink: 0;
  margin: 0 18px;
  overflow: visible;
}
.cards-carousel__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform-origin: center;
  transition: transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.cards-carousel__image-fallback {
  display: grid;
  place-items: center;
  background: var(--feedback-soft);
  color: var(--feedback-muted);
  font-size: 12px;
}
.cards-carousel__card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 20px;
  font-size: 11px;
}
.cards-carousel__plus {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 2px solid var(--story-border);
  border-radius: 8px;
  box-shadow: 0 3px 0 var(--story-border);
  transition:
    transform 180ms ease-out,
    box-shadow 180ms ease-out;
}
.cards-carousel__plus svg {
  width: 20px;
  height: 20px;
  transition: transform 240ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@media (hover: hover) {
  .cards-carousel__card:hover {
    transform: translateY(-8px);
    box-shadow: 0 9px 0 var(--story-border);
  }
  .cards-carousel__card:hover .cards-carousel__image {
    transform: scale(1.045);
  }
  .cards-carousel__card:hover .cards-carousel__plus {
    transform: translateY(2px);
    box-shadow: 0 1px 0 var(--story-border);
  }
  .cards-carousel__card:hover .cards-carousel__plus svg {
    transform: rotate(90deg);
  }
}
.cards-carousel__card:focus-visible {
  transform: translateY(-8px);
  box-shadow: 0 9px 0 var(--story-border);
}
.cards-carousel__card:active {
  transform: translateY(3px);
  box-shadow: 0 2px 0 var(--story-border);
}
.cards-carousel__card:focus-visible {
  outline: none;
}
.cards-carousel__navigation {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 32px 32px;
}
.cards-carousel__navigation > span {
  font-size: 12px;
  line-height: 1.6;
  color: var(--feedback-muted);
}
.cards-carousel__progress {
  display: block;
  width: clamp(80px, 18vw, 200px);
  height: 6px;
  margin-top: 12px;
  overflow: hidden;
  border: 1px solid var(--story-border);
  border-radius: 3px;
  background: var(--feedback-soft);
}
.cards-carousel__progress > span {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--feedback-ink);
  transform-origin: left;
  transform: scaleX(calc(0.12 + var(--collection-progress, 0) * 0.88));
}
.cards-carousel__navigation > div {
  display: flex;
  gap: 12px;
}
.cards-carousel__navigation .duoop-button,
.cards-carousel__detail-heading .duoop-button {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
}
.cards-carousel__empty {
  padding: 48px 0;
  color: var(--feedback-muted);
}
.cards-carousel[data-size='compact'] .cards-carousel__card {
  flex-basis: 240px;
}
.cards-carousel[data-size='compact'] .cards-carousel__copy {
  min-height: 144px;
  padding: 20px;
}
.cards-carousel[data-size='compact'] .cards-carousel__copy strong {
  font-size: 22px;
}
.cards-carousel[data-size='compact'] .cards-carousel__window {
  height: 184px;
}
.cards-carousel__dialog {
  width: min(800px, calc(100% - 32px));
  max-height: calc(100dvh - 48px);
  padding: 0;
  border: 2px solid var(--story-border);
  border-radius: 12px;
  background: var(--feedback-face);
  color: var(--feedback-ink);
  box-shadow: 0 6px 0 var(--story-border);
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--feedback-muted) transparent;
}
.cards-carousel__dialog[open] {
  animation: story-enter 240ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.cards-carousel__dialog::backdrop {
  background: rgb(29 27 27 / 0.6);
  animation: story-fade 180ms ease-out;
}
.cards-carousel__detail-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 32px;
  border-bottom: 1px solid var(--feedback-track);
}
.cards-carousel__detail-toolbar > .cards-carousel__eyebrow {
  color: var(--feedback-muted);
}
.cards-carousel__detail-toolbar > .cards-carousel__eyebrow > span {
  margin-inline: 12px;
}
.cards-carousel__detail-toolbar .duoop-button,
.cards-carousel__detail-footer nav .duoop-button {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
}
.cards-carousel__story {
  animation: story-enter 240ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.cards-carousel__detail-heading {
  display: flex;
  align-items: start;
  gap: 24px;
  padding: 28px 32px;
}
.cards-carousel__story-number {
  display: grid;
  place-items: center;
  flex: 0 0 56px;
  height: 64px;
  font-size: 27px;
  font-weight: 500;
  letter-spacing: -1px;
  border: 2px solid var(--story-border);
  border-radius: 8px;
  box-shadow: 0 4px 0 var(--story-border);
  background: var(--feedback-soft);
  font-variant-numeric: tabular-nums;
}
.cards-carousel__detail-heading h2 {
  max-width: 570px;
  margin: 10px 0 0;
  font-size: clamp(26px, 4vw, 36px);
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -1px;
  text-wrap: balance;
}
.cards-carousel__detail-heading h2:focus {
  outline: none;
}
.cards-carousel__detail-heading h2:focus-visible {
  text-decoration: underline;
  text-decoration-style: solid;
  text-decoration-thickness: 1px;
  text-underline-offset: 6px;
}
.cards-carousel__figure {
  margin: 0 32px;
}
.cards-carousel__detail-image {
  display: block;
  width: 100%;
  height: 240px;
  object-fit: cover;
  border: 2px solid var(--story-border);
  border-radius: 8px;
}
.cards-carousel__figure figcaption {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 10px;
  font-size: 11px;
  line-height: 1.5;
  color: var(--feedback-muted);
}
.cards-carousel__figure figcaption > span:last-child {
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.cards-carousel__detail-content {
  display: flex;
  align-items: start;
  gap: 28px;
  padding: 28px 32px 32px;
  font-size: 14px;
  line-height: 1.8;
}
.cards-carousel__prose {
  flex: 1;
  min-width: 0;
}
.cards-carousel__detail-content h3 {
  margin: 0 0 12px;
  font-size: 21px;
  line-height: 1.3;
  letter-spacing: -0.4px;
}
.cards-carousel__detail-content p {
  margin: 0 0 20px;
  color: var(--feedback-muted);
}
.cards-carousel__detail-content p:last-child {
  margin: 0;
}
.cards-carousel__takeaway {
  flex: 0 0 180px;
  padding: 16px 0 0 20px;
  border-inline-start: 2px solid var(--story-border);
}
.cards-carousel__takeaway > svg {
  display: block;
  width: 32px;
  height: 32px;
  margin-bottom: 16px;
}
.cards-carousel__takeaway .cards-carousel__eyebrow {
  margin-bottom: 10px;
}
.cards-carousel__detail-content .cards-carousel__takeaway p {
  font-size: 12px;
  line-height: 1.8;
  color: var(--feedback-ink);
}
.cards-carousel__detail-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 32px 24px;
  border-top: 2px solid var(--story-border);
  background: var(--feedback-soft);
}
.cards-carousel__detail-footer nav {
  display: flex;
  align-items: center;
  gap: 16px;
}
.cards-carousel__story-position {
  white-space: nowrap;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.cards-carousel__story-position > span {
  color: var(--feedback-muted);
  font-weight: 400;
}
.cards-carousel__detail-footer .duoop-button-reserve {
  display: none;
}
.cards-playground {
  margin-top: 32px;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.cards-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 32px;
  padding: 24px 32px;
  border-top: 1px solid var(--border);
}
.cards-controls fieldset {
  padding: 0;
  margin: 0;
  border: 0;
  min-width: 0;
}
.cards-controls legend {
  margin-bottom: 12px;
  font-size: 12px;
  font-weight: 600;
}
.cards-controls fieldset > div {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.cards-controls .duoop-button-reserve {
  display: none;
}
.cards-carousel-showcase .gallery-grid {
  grid-template-columns: minmax(0, 1fr);
}
.cards-carousel-showcase .gallery-card-preview {
  padding: 0;
}
.cards-mini {
  display: flex;
  gap: 12px;
  width: 262px;
}
.cards-mini > span {
  flex: 0 0 124px;
  display: flex;
  flex-direction: column;
  border: 2px solid #1d1b1b;
  border-radius: 8px;
  background: #fff;
  overflow: hidden;
  box-shadow: 0 4px 0 #1d1b1b;
  transition: transform 200ms ease-out;
}
.cards-mini > span:last-child {
  transform: translateY(12px);
}
.cards-mini strong {
  text-transform: uppercase;
  font-weight: 800;
  font-size: 13px;
  line-height: 1.2;
  padding: 12px;
}
.cards-mini img {
  width: calc(100% - 16px);
  margin: 0 8px 10px;
  height: 90px;
  object-fit: cover;
  border: 2px solid #1d1b1b;
  border-radius: 60px 60px 5px 5px;
}
.library-card:hover .cards-mini > span:last-child {
  transform: translateY(-6px);
}
@keyframes story-enter {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes story-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (max-width: 600px) {
  .cards-carousel__heading {
    padding: 24px 20px 8px;
  }
  .cards-carousel__hint {
    display: none;
  }
  .cards-carousel__rail {
    padding-inline: 20px;
    scroll-padding-inline: 20px;
  }
  .cards-carousel__card,
  .cards-carousel[data-size='compact'] .cards-carousel__card {
    flex-basis: min(280px, 88%);
  }
  .cards-carousel__copy {
    padding: 20px;
  }
  .cards-carousel__navigation {
    padding: 16px 20px 24px;
  }
  .cards-controls {
    padding: 24px 20px;
    gap: 24px;
  }
  .cards-carousel__detail-heading,
  .cards-carousel__detail-content {
    padding: 24px 20px;
  }
  .cards-carousel__detail-heading {
    gap: 16px;
  }
  .cards-carousel__story-number {
    flex-basis: 42px;
    height: 50px;
    font-size: 22px;
  }
  .cards-carousel__detail-toolbar {
    padding: 12px 20px;
  }
  .cards-carousel__detail-toolbar > .cards-carousel__eyebrow > span {
    margin-inline: 4px;
  }
  .cards-carousel__figure {
    margin-inline: 20px;
  }
  .cards-carousel__detail-image {
    height: 200px;
  }
  .cards-carousel__detail-content {
    flex-direction: column;
    gap: 24px;
  }
  .cards-carousel__takeaway {
    flex: auto;
    width: 100%;
    padding: 16px 20px;
    border: 1px solid var(--feedback-track);
    border-inline-start: 2px solid var(--story-border);
    border-radius: 0 8px 8px 0;
    background: var(--feedback-soft);
  }
  .cards-carousel__takeaway > svg {
    display: none;
  }
  .cards-carousel__detail-footer {
    padding: 20px;
    flex-wrap: wrap;
  }
  .cards-carousel__detail-footer nav {
    justify-content: space-between;
    flex: 1;
  }
  .cards-carousel__return {
    order: 1;
    width: 100%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .cards-carousel__card,
  .cards-carousel__image,
  .cards-carousel__plus,
  .cards-carousel__plus svg,
  .cards-mini > span {
    transition: none;
  }
  .cards-carousel__card,
  .cards-carousel__card:focus-visible,
  .cards-carousel__card:hover .cards-carousel__image,
  .cards-carousel__card:hover .cards-carousel__plus svg,
  .cards-carousel__card:hover,
  .cards-carousel__card:active,
  .cards-carousel__card:hover .cards-carousel__plus,
  .library-card:hover .cards-mini > span:last-child {
    transform: none;
  }
  .cards-carousel__dialog[open],
  .cards-carousel__story {
    animation: story-fade 120ms ease-out;
  }
}

