  margin-inline: -28px;
  border-top: 1px solid #e2dede;
  background: #f7f6f4;
}
.testimonials--wall .testimonials__heading {
  text-align: center;
  margin: 0 auto 32px;
}
.testimonials--wall .testimonials__heading p {
  margin-inline: auto;
}
.testimonials__choices {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}
.testimonials__choices .duoop-button {
  width: 100%;
  min-height: 76px;
}
.testimonials__choice {
  display: grid;
  gap: 5px;
  padding: 4px;
  text-align: start;
}
.testimonials__choice strong {
  font-size: 16px;
  letter-spacing: -0.03em;
}
.testimonials__choice small {
  font-size: 11px;
  font-weight: 400;
}
.testimonials--voices .testimonials__stage {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  gap: 24px;
  align-items: start;
}
.testimonials--voices {
  background: #eeece9;
}
.testimonials-showcase .gallery-card--wide {
  grid-column: 1 / -1;
}
.testimonials-showcase .gallery-card-preview {
  padding: 20px;
}
.testimonials-showcase .individual-preview {
  display: block;
}
.testimonials-reference {
  font-size: 12px;
  color: #717781;
  line-height: 1.7;
}
.testimonials-mini {
  display: grid;
  width: 220px;
  padding: 20px;
  border: 2px solid #1d1b1b;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 4px 0 #1d1b1b;
  gap: 10px;
  transform: rotate(-3deg);
  color: #373434;
}
.testimonials-mini .testimonials__mark {
  width: 26px;
  height: 22px;
}
.testimonials-mini strong {
  font-size: 15px;
  letter-spacing: -0.03em;
}
.testimonials-mini small {
  font-size: 10px;
  color: #686565;
}
@container (max-width:700px) {
  .testimonials__wall {
    grid-template-columns: 1fr 1fr;
  }
  .testimonials__wall-center {
    grid-column: 1 / -1;
    grid-row: 1;
  }
  .testimonials--voices .testimonials__stage {
    grid-template-columns: 1fr;
  }
  .testimonials__choices {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .testimonials__choices .duoop-button {
    flex: 1;
    min-width: 120px;
  }
}
@container (max-width:420px) {
  .testimonials__wall,
  .testimonials__wall-lower {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .testimonials__wall .testimonials__quote--featured {
    padding: 24px 20px 0;
  }
  .testimonials__wall .testimonials__quote--featured .testimonials__author {
    margin-inline: -20px;
    padding: 20px;
  }
  .testimonials__paper {
    padding: 20px;
  }
  .testimonials__company {
    flex-wrap: wrap;
  }
  .testimonials__quote--featured {
    display: block;
    padding-top: 24px;
  }
  .testimonials__quote--featured > .testimonials__mark {
    width: 64px;
    height: auto;
    margin: 0;
  }
  .testimonials__quote--featured blockquote {
    min-height: 0;
  }
}
@media (max-width: 650px) {
  .testimonials {
    padding: 24px 16px;
  }
  .testimonials-showcase .gallery-card-preview {
    padding: 8px;
  }
}
@keyframes testimonial-arrive {
  from {
    opacity: 0;
    transform: translateX(calc(var(--testimonial-direction) * 28px));
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.testimonials--voices .testimonials__story {
  animation-name: testimonial-fade;
}
@keyframes testimonial-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .testimonials__wall .testimonials__quote {
    transition:
      transform 220ms ease,
      box-shadow 220ms ease;
  }
  .testimonials__wall .testimonials__quote:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 0 var(--testimonial-edge);
  }
}
@media (prefers-reduced-motion: reduce) {
  .testimonials .testimonials__story {
    animation: none;
  }
}

