    company: 'Offset',
    quote:
      'Design and engineering finally speak the same language. Even the quietest details get the attention they deserve.',
  },
];
const wallItems = [
  ...testimonialItems,
  {
    id: 'eli',
    name: 'Eli Brooks',
    role: 'Developer',
    company: 'Fieldwork',
    quote:
      'The code is easy to follow. We can adjust a component and still understand it a month later.',
