import React, { useId, useLayoutEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { FeedbackIcon } from '../Feedback/FeedbackIcon';
import '../Feedback/Feedback.css';
import './Progress.css';

export const progressStates = {
  waiting: 'Waiting',
  preparing: 'Preparing…',
  running: 'In progress',
  paused: 'Paused',
  finalizing: 'Finalizing…',
  success: 'Complete',
  error: 'Failed',
  cancelled: 'Cancelled',
  partial: 'Partially complete',
};

/** Controlled progress: reaching max does not imply a confirmed success. */
export function Progress({
  value = 0,
  max = 100,
  state = 'running',
  shape = 'linear',
  size = 'md',
  label = 'Progress',
  hideLabel = false,
  display = 'percent',
  description,
  buffer,
  segments = 0,
  rounded = true,
  textPosition = 'above',
  children,
  className = '',
  ...props
}) {
  const id = useId();
  const root = useRef(null);
  const drawn = useRef(null);
  const limit = Number.isFinite(max) && max > 0 ? max : 100;
  const current = Number.isFinite(value) ? Math.min(limit, Math.max(0, value)) : 0;
  const indefinite = value === null || state === 'preparing';
  const percent = (current / limit) * 100;
  const buffered = Number.isFinite(buffer)
    ? Math.max(percent, Math.min(100, (buffer / limit) * 100))
    : percent;
  const status = progressStates[state] || progressStates.running;
  const amount = indefinite
    ? status
    : display === 'quantity'
      ? `${current} / ${limit}`
      : `${Math.round(percent)}%`;
  const terminal = ['success', 'error', 'cancelled', 'partial'].includes(state);
  const ring = shape === 'circular';
  useLayoutEffect(() => {
    const node = root.current;
    const fill = node.querySelector('.progress-fill');
    const arc = node.querySelector('.progress-ring-fill');
    const counter = node.querySelector('[data-progress-counter]');
    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
    let tween;
    const model = { percent: drawn.current ?? percent };
    const paint = () => {
      drawn.current = model.percent;
      if (fill) fill.style.transform = `scaleX(${model.percent / 100})`;
      if (arc) arc.style.strokeDasharray = `${model.percent} 100`;
      if (counter && display === 'percent')
        counter.textContent = `${Math.round(model.percent)}%`;
    };
    const update = () => {
      tween?.kill();
      if (indefinite) {
        drawn.current = null;
        return;
      }
      if (
        media.matches ||
        ['paused', 'waiting', 'error', 'cancelled'].includes(state)
      ) {
        model.percent = percent;
        paint();
      } else {
        paint();
        tween = gsap.to(model, {
          percent,
          duration: 0.6,
          ease: 'power3.out',
          onUpdate: paint,
        });
      }
    };
    update();
    media.addEventListener('change', update);
    return () => {
      tween?.kill();
      media.removeEventListener('change', update);
    };
  }, [percent, indefinite, state, ring, display]);

  return (
    <div
      ref={root}
      className={`duoop-progress ${className}`}
      data-state={state}
      data-shape={shape}
      data-size={size}
      data-rounded={rounded}
      data-text-position={textPosition}
      data-indeterminate={indefinite}
    >
      <div
        className={`progress-heading ${hideLabel && (display === 'none' || ring) ? 'duoop-sr-only' : ''}`}
      >
        <span id={`${id}-label`} className={hideLabel ? 'duoop-sr-only' : ''}>
          {label}
        </span>
        {!ring && display !== 'none' && (
          <span className="progress-value" data-progress-counter aria-hidden="true">
            {amount}
          </span>
        )}
      </div>
      <div
        {...props}
        className="progress-meter"
        role="progressbar"
        aria-labelledby={`${id}-label`}
        aria-describedby={`${id}-status`}
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={indefinite ? undefined : current}
        aria-valuetext={`${status}${indefinite ? '' : `, ${amount}`}`}
      >
        {ring ? (
          <div className="progress-ring">
            <svg viewBox="0 0 120 120" aria-hidden="true">
              <circle className="progress-ring-edge" cx="60" cy="60" r="50" />
              <circle className="progress-ring-track" cx="60" cy="60" r="50" />
              <circle
                className="progress-ring-fill"
                cx="60"
                cy="60"
                r="50"
                pathLength="100"
                style={{ strokeDasharray: `${indefinite ? 26 : percent} 100` }}
              />
            </svg>
            <span className="progress-ring-center" key={terminal ? state : 'value'}>
              {terminal ? (
                <FeedbackIcon status={state} />
              ) : (
                children ||
                (!indefinite && display !== 'none' ? (
                  <strong data-progress-counter aria-hidden="true">
                    {amount}
                  </strong>
                ) : null)
              )}
            </span>
          </div>
        ) : (
          <div className="progress-track">
            {buffer !== undefined && (
              <span
                className="progress-buffer"
                style={{ transform: `scaleX(${buffered / 100})` }}
              />
            )}
            <span
              className="progress-fill"
              style={
                indefinite ? undefined : { transform: `scaleX(${percent / 100})` }
              }
            />
            {segments > 1 && (
              <span className="progress-segments" aria-hidden="true">
                {Array.from(
                  { length: Math.min(100, Math.floor(segments)) - 1 },
                  (_, i) => (
                    <i
                      key={i}
                      style={{
                        insetInlineStart: `${((i + 1) / Math.min(100, Math.floor(segments))) * 100}%`,
                      }}
                    />
                  ),
                )}
              </span>
            )}
          </div>
        )}
        {state === 'success' && (
          <span className="progress-arrival" aria-hidden="true" />
        )}
      </div>
      <div className="progress-caption" id={`${id}-status`}>
        <span className="progress-status" role="status">
          {(state !== 'running' || (ring && indefinite)) && (
            <>
              {state !== 'running' && <FeedbackIcon key={state} status={state} />}
              {status}
            </>
          )}
        </span>
        {description && <span>{description}</span>}
      </div>
    </div>
  );
}

sources.dd16cd0ae8afb0df5182f4e85b50a7a4084b723f:
.duoop-progress {
  --progress-tone: var(--feedback-ink, #373434);
  width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  color: var(--feedback-ink, #373434);
}
.duoop-progress[data-state='success'] {
  --progress-tone: var(--feedback-success, #356247);
}
.duoop-progress[data-state='error'] {
  --progress-tone: var(--feedback-error, #a51d2d);
}
.duoop-progress[data-state='partial'] {
  --progress-tone: var(--feedback-warning, #80521a);
}
.duoop-progress:is(
  [data-state='paused'],
  [data-state='cancelled'],
  [data-state='waiting']
) {
  --progress-tone: var(--feedback-muted, #686565);
}
.progress-heading {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: baseline;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.5;
}
.progress-heading > span {
  overflow-wrap: anywhere;
}
.progress-value {
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
  color: var(--progress-tone);
}
.progress-track {
  position: relative;
  height: 16px;
  border-radius: 6px;
  box-shadow: 0 3px 0 var(--feedback-edge, #1d1b1b);
  background: var(--feedback-track, #e8e4e4);
  overflow: hidden;
  isolation: isolate;
}
.duoop-progress[data-size='sm'] .progress-track {
  height: 8px;
  border-radius: 3px;
  box-shadow: 0 2px 0 var(--feedback-edge, #1d1b1b);
}
.duoop-progress[data-size='lg'] .progress-track {
  height: 24px;
  border-radius: 7px;
}
.duoop-progress[data-rounded='false'] .progress-track {
  border-radius: 0;
}
.progress-track::after {
  content: '';
  position: absolute;
  inset: 0;
  border: 2px solid var(--feedback-edge, #1d1b1b);
  border-radius: inherit;
  z-index: 2;
  pointer-events: none;
}
.progress-fill,
.progress-buffer {
  position: absolute;
  inset: 0;
  transform-origin: left;
  transition: background-color 240ms ease;
}
.progress-buffer {
  transition:
    transform 750ms cubic-bezier(0.2, 0.8, 0.2, 1),
    background-color 240ms ease;
}
[dir='rtl'] .progress-fill,
[dir='rtl'] .progress-buffer {
  transform-origin: right;
}
.progress-fill {
  background: var(--progress-tone);
  overflow: hidden;
}
.progress-fill::before {
  content: '';
  position: absolute;
  inset: 3px 6px auto;
  height: 3px;
  border-radius: 3px;
  background: var(--feedback-face, #fff);
  opacity: 0.28;
}
.duoop-progress[data-size='sm'] .progress-fill::before {
  inset-block-start: 2px;
  height: 1px;
}
.duoop-progress[data-size='lg'] .progress-fill::before {
  inset-block-start: 4px;
  height: 4px;
}
.progress-meter {
  position: relative;
}
.progress-arrival {
  position: absolute;
  inset: -4px;
  border: 2px solid var(--progress-tone);
  border-radius: 9px;
  pointer-events: none;
  opacity: 0;
  animation: progress-arrival 750ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.duoop-progress[data-shape='circular'] .progress-arrival {
  border-radius: 50%;
  inset: 4px;
}
.duoop-progress[data-shape='linear'][data-state='success'] .progress-track {
  animation: progress-land 600ms cubic-bezier(0.2, 1.5, 0.3, 1);
}
.progress-buffer {
  background: var(--progress-tone);
  opacity: 0.24;
}
.progress-segments {
  position: absolute;
  inset: 0;
}
.progress-segments i {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--feedback-face, #fff);
  border-inline-start: 1px solid var(--feedback-edge, #1d1b1b);
}
.duoop-progress[data-indeterminate='true'] .progress-fill {
  width: 35%;
  animation: progress-sweep 1.4s cubic-bezier(0.4, 0, 0.2, 1) infinite;
}
.progress-caption {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 12px;
  line-height: 1.65;
  color: var(--feedback-muted, #686565);
  overflow-wrap: anywhere;
}
.progress-caption:has(.progress-status:empty):not(:has(> span + span)) {
  display: none;
}
.progress-status {
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--progress-tone);
  font-weight: 600;
}
.progress-status:empty {
  display: none;
}
.progress-status svg {
  width: 18px;
  height: 18px;
}
.duoop-progress[data-shape='circular'] {
  align-items: center;
  text-align: center;
}
.progress-ring {
  width: 124px;
  height: 124px;
  position: relative;
}
.duoop-progress[data-size='sm'] .progress-ring {
  width: 76px;
  height: 76px;
}
.duoop-progress[data-size='lg'] .progress-ring {
  width: 164px;
  height: 164px;
}
.progress-ring > svg {
  width: 100%;
  height: 100%;
  fill: none;
  transform: rotate(-90deg);
  overflow: visible;
  filter: drop-shadow(-2px 0 0 var(--feedback-edge, #1d1b1b));
}
.progress-ring-edge {
  stroke: var(--feedback-edge, #1d1b1b);
  stroke-width: 12;
}
.progress-ring-track {
  stroke: var(--feedback-track, #e8e4e4);
  stroke-width: 8;
}
.progress-ring-fill {
  stroke: var(--progress-tone);
  stroke-width: 8.5;
  stroke-linecap: round;
  transition: stroke 240ms ease;
}
.duoop-progress[data-rounded='false'] .progress-ring-fill {
  stroke-linecap: butt;
}
.progress-ring-center {
  position: absolute;
  inset: 18%;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
  justify-content: center;
  color: var(--progress-tone);
  font-size: 20px;
  font-variant-numeric: tabular-nums;
}
.progress-ring-center > svg {
  width: 36px;
  height: 36px;
}
.progress-ring-center small {
  font-size: 11px;
}
.duoop-progress[data-size='sm'] .progress-ring-center {
  font-size: 12px;
}
.duoop-progress[data-indeterminate='true'] .progress-ring > svg {
  animation: duoop-spin 1.3s linear infinite;
}
.duoop-progress:is(
    [data-state='paused'],
    [data-state='cancelled'],
    [data-state='error']
  )
  * {
  animation-play-state: paused;
}
.duoop-progress[data-state='success'] .progress-ring-center {
  animation: progress-confirm 650ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.duoop-progress[data-state='success'] .progress-ring-center .duoop-check {
  animation: none;
}
.duoop-progress[data-state='success'] .progress-ring-center .duoop-check path {
  animation: duoop-draw 420ms ease-out 180ms both;
}
.duoop-progress[data-shape='linear'][data-text-position='below'] .progress-heading {
  order: 1;
}
.duoop-progress[data-shape='linear'][data-text-position='below'] .progress-caption {
  order: 2;
}
.duoop-progress[data-shape='linear'][data-text-position='beside'] {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(80px, 1fr);
  align-items: center;
}
.duoop-progress[data-shape='linear'][data-text-position='beside'] .progress-caption {
  grid-column: 1/-1;
}
.progress-transfer {
  display: flex;
  align-items: center;
  gap: 16px;
}
.progress-file-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 56px;
  flex: none;
  border: 2px solid var(--feedback-edge);
  border-radius: 8px;
  box-shadow: 0 3px 0 var(--feedback-edge);
  background: var(--feedback-face);
}
.progress-transfer > div {
  flex: 1;
  min-width: 0;
}
.progress-page-demo {
  border: 2px solid var(--feedback-edge);
  border-radius: 10px;
  background: var(--feedback-face);
  overflow: hidden;
  box-shadow: 0 4px 0 var(--feedback-edge);
}
.progress-page-demo .progress-track {
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.progress-page-demo .progress-track::after {
  border: 0;
}
.progress-page-demo .progress-caption {
  padding: 0 20px;
}
.progress-page-copy {
  padding: 28px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-size: 13px;
}
.progress-page-copy span {
  color: var(--feedback-muted);
  font-size: 12px;
}
.progress-multiple {
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.progress-multiple > div + div {
  border-top: 1px solid var(--feedback-track);
  padding-top: 20px;
}
@keyframes progress-sweep {
  from {
    transform: translateX(-110%);
  }
  to {
    transform: translateX(390%);
  }
}
@keyframes progress-confirm {
  0% {
    opacity: 0;
    transform: translateY(8px) scale(0.55) rotate(-18deg);
  }
  60% {
    opacity: 1;
    transform: translateY(-2px) scale(1.12) rotate(3deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes progress-arrival {
  from {
    opacity: 0.5;
    transform: scale(0.96);
  }
  to {
    opacity: 0;
    transform: scale(1.1, 1.6);
  }
}
.duoop-progress[data-shape='circular'] .progress-arrival {
  animation-name: progress-ring-arrival;
}
@keyframes progress-ring-arrival {
  from {
    opacity: 0.55;
    transform: scale(0.92);
  }
  to {
    opacity: 0;
    transform: scale(1.24);
  }
}
@keyframes progress-land {
  0% {
    transform: scaleY(0.8);
  }
  45% {
    transform: scaleY(1.15);
  }
  to {
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .progress-fill,
  .progress-buffer,
  .progress-ring-fill {
    transition: none;
  }
  .duoop-progress[data-indeterminate='true'] .progress-fill,
  .duoop-progress[data-indeterminate='true'] .progress-ring > svg,
  .duoop-progress[data-state='success'] .progress-ring-center {
    animation: none;
  }
  .duoop-progress[data-indeterminate='true'] .progress-fill {
    transform: translateX(90%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .progress-arrival {
    display: none;
  }
  .duoop-progress[data-state='success'] .progress-track,
  .duoop-progress[data-state='success'] .progress-ring-center .duoop-check path {
    animation: none;
  }
}

sources.a10711efe1e39de0d2bcd00258bcb4f2de7bdff2:
.duoop-toast {
  --toast-tone: var(--feedback-ink);
  --toast-tint: var(--feedback-soft);
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  width: 100%;
  padding: 20px;
  border: 2px solid var(--feedback-edge);
  border-radius: 10px;
  background: var(--feedback-face);
  color: var(--feedback-ink);
  box-shadow: 0 4px 0 var(--feedback-edge);
  animation: toast-enter 280ms cubic-bezier(0.2, 1.2, 0.4, 1) both;
  transition: border-color 220ms ease;
  overflow-wrap: anywhere;
}
.duoop-toast[data-tone='success'] {
  --toast-tone: var(--feedback-success);
  --toast-tint: var(--feedback-success-soft);
}
.duoop-toast[data-tone='error'] {
  --toast-tone: var(--feedback-error);
  --toast-tint: var(--feedback-error-soft);
}
.duoop-toast[data-tone='warning'] {
  --toast-tone: var(--feedback-warning);
  --toast-tint: var(--feedback-warning-soft);
}
.duoop-toast[data-appearance='tinted'] {
  background: var(--toast-tint);
  border-color: var(--toast-tone);
  box-shadow: 0 4px 0 var(--toast-tone);
}
.duoop-toast[data-appearance='solid'] {
  background: var(--toast-tone);
  color: var(--feedback-face);
  border-color: var(--feedback-edge);
}
.duoop-toast[data-appearance='solid'] .toast-status-icon,
.duoop-toast[data-appearance='solid'] .toast-content > p {
  color: inherit;
}
.toast-status-icon {
  width: 24px;
  min-height: 24px;
  display: grid;
  place-items: center;
  flex: none;
  color: var(--toast-tone);
  animation: toast-status-in 260ms ease-out;
}
.toast-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.toast-title {
  font-size: 13px;
  line-height: 1.65;
  font-weight: 650;
  animation: toast-renotify 240ms ease-out;
}
.toast-content > p {
  font-size: 12px;
  line-height: 1.7;
  color: var(--feedback-muted);
  margin: 0;
}
.toast-content > .duoop-button {
  align-self: flex-start;
  margin-top: 4px;
}
.duoop-toast .toast-close {
  width: 28px;
  min-height: 28px;
  padding: 4px;
  border-radius: 6px;
  --button-depth: 2px;
  flex: none;
  margin: -4px -4px 0 0;
}
.toast-close .feedback-icon {
  width: 14px;
  height: 14px;
}
.duoop-toast[data-density='compact'] {
  padding: 12px;
  gap: 8px;
}
.duoop-toast[data-density='compact'] .toast-title {
  font-size: 12px;
}
.toast-countdown {
  height: 4px;
  border-radius: 2px;
  overflow: hidden;
  background: var(--feedback-track);
}
.toast-countdown > span {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--toast-tone);
  transform-origin: left;
  transition: transform 100ms linear;
}
.duoop-toast[data-leaving='true'] {
  animation: toast-exit 220ms ease-in forwards;
  pointer-events: none;
}
.toast-viewport {
  position: fixed;
  width: 380px;
  max-width: calc(100vw - 32px);
  z-index: 1500;
  pointer-events: none;
  outline: none;
}
.toast-viewport[data-position^='bottom'] {
  bottom: max(24px, env(safe-area-inset-bottom));
}
.toast-viewport[data-position^='top'] {
  top: max(24px, env(safe-area-inset-top));
}
.toast-viewport[data-position$='right'] {
  right: 24px;
}
.toast-viewport[data-position$='left'] {
  left: 24px;
}
.toast-viewport[data-position$='center'] {
  left: 50%;
  transform: translateX(-50%);
}
.toast-viewport:focus-visible .toast-stack .duoop-toast {
  border-style: solid;
}
.toast-viewport.toast-viewport--inline {
  position: relative;
  width: 100%;
  max-width: none;
  inset: auto;
  transform: none;
  z-index: 1;
}
.toast-stack {
  position: relative;
  pointer-events: auto;
  transition: height 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.toast-slot {
  position: absolute;
  inset: 0 0 auto;
  transform-origin: top center;
  transition: transform 280ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.toast-slot[data-covered='true'] {
  pointer-events: none;
}
.toast-slot[data-covered='true'] .duoop-toast > * {
  opacity: 0;
}
.toast-slot .duoop-toast > * {
  transition: opacity 160ms ease;
}
.toast-queue-count {
  display: block;
  text-align: center;
  font-size: 11px;
  color: var(--feedback-muted);
  margin-top: 14px;
  padding: 4px;
  background: var(--feedback-face);
}
.toast-anchor {
  z-index: 1600;
  width: max-content;
  max-width: min(380px, calc(100vw - 24px));
}
.toast-anchor .duoop-toast {
  width: 100%;
}
.toast-demo-stage {
  min-height: 100px;
  display: flex;
  align-items: center;
  width: 100%;
}
.toast-demo-stage > .toast-viewport {
  flex: 1;
}
.toast-file-state {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 28px;
  font-size: 12px;
  color: var(--feedback-muted);
}
.toast-file-state > svg {
  width: 20px;
  height: 20px;
}
.toast-anchor-preview {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.toast-copy-path {
  font-size: 12px;
  overflow-wrap: anywhere;
}
.toast-file-details {
  border-top: 1px solid var(--feedback-track);
  padding-top: 20px;
  font-size: 13px;
  line-height: 1.7;
}
.toast-file-details:focus {
  outline: none;
  border-top-style: solid;
}
.toast-viewport:not(.toast-viewport--inline) {
  max-height: calc(100dvh - 64px);
  overflow-y: auto;
  padding-bottom: 6px;
}
@keyframes toast-enter {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@keyframes toast-exit {
  to {
    opacity: 0;
    transform: translateY(8px) scale(0.96);
  }
}
@keyframes toast-status-in {
  from {
    opacity: 0;
    transform: scale(0.7);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes toast-renotify {
  from {
    opacity: 0.4;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (pointer: coarse) {
  .duoop-toast .toast-close {
    min-width: 44px;
    min-height: 44px;
  }
}
@media (max-width: 650px) {
  .toast-viewport:not(.toast-viewport--inline) {
    width: calc(100vw - 32px);
  }
  .toast-viewport[data-position$='right'] {
    right: 16px;
  }
  .toast-viewport[data-position$='left'] {
    left: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-toast,
  .toast-status-icon,
  .toast-title,
  .duoop-toast[data-leaving='true'] {
    animation: none;
  }
  .duoop-toast[data-leaving='true'] {
    opacity: 0;
  }
  .toast-slot,
  .toast-stack,
  .toast-countdown > span,
  .toast-slot .duoop-toast > * {
    transition: none;
  }
}
.toast-placement-field {
  grid-template-columns: minmax(0, 1fr) minmax(180px, 220px);
  align-items: center;
  gap: 16px;
}
.toast-placement-field .duoop-select {
  min-width: 0;
}
@media (max-width: 500px) {
  .toast-placement-field {
    grid-template-columns: minmax(0, 1fr);
  }
}

