  border: 1px solid #e7e9ed;
  border-radius: 12px;
  overflow: hidden;
  margin: 32px 0 48px;
}
.avatar-lab > header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 28px 32px;
}
.avatar-lab h3 {
  font-size: 23px;
  font-weight: 600;
