.duoop-calendar {
  --day-size: 40px;
  box-sizing: border-box;
  width: 324px;
  max-width: 100%;
  padding: 20px;
  border: 2px solid #373434;
  border-radius: 12px;
  box-shadow: 0 4px 0 #1d1b1b;
  background: #fff;
  color: #373434;
  font:
    400 14px/1.5 'DM Sans',
    sans-serif;
}
.duoop-calendar .rdp-months {
  position: relative;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}
.duoop-calendar .rdp-month {
  min-width: 0;
}
.duoop-calendar .rdp-month_caption {
