import React, { useId, useRef, useState } from 'react';
import './Folder.css';

const flapPath =
  'M24 236Q8 236 8 220V28Q8 12 24 12H108Q119 12 126 21L139 37Q146 46 158 46H376Q392 46 392 62V220Q392 236 376 236Z';

/** A small document collection. Item IDs must be unique and stable. */
export function Folder({
  items = [],
  label = 'Documents',
  defaultOpen = false,
  onSelect,
  className = '',
}) {
  const [open, setOpen] = useState(defaultOpen);
  const [hovered, setHovered] = useState(false);
  const [selected, setSelected] = useState(null);
  const trigger = useRef(null);
  const id = useId();
  const state = open ? 'expanded' : hovered ? 'preview' : 'closed';
  return (
    <div
      className={`duoop-folder ${className}`}
      data-open={open}
      data-state={state}
      onPointerLeave={() => setHovered(false)}
      onKeyDown={(event) => {
        if (event.key === 'Escape') {
          event.stopPropagation();
          setOpen(false);
          setHovered(false);
          trigger.current?.focus();
        }
      }}
    >
      <svg
        className="duoop-folder__back"
        viewBox="0 0 400 250"
        fill="none"
        aria-hidden="true"
      >
        <path
          d={flapPath}
          fill="#e7e3e1"
          stroke="#1d1b1b"
          strokeWidth="3.5"
          strokeLinejoin="round"
        />
      </svg>
      <div
        className="duoop-folder__cover"
        onPointerEnter={(event) => {
          if (event.pointerType === 'mouse') setHovered(true);
        }}
        onPointerLeave={() => setHovered(false)}
      >
        <button
          ref={trigger}
          type="button"
          className="duoop-folder__front"
          aria-expanded={open}
          aria-controls={id}
          onClick={() => setOpen((value) => !value)}
        >
          <svg
            className="duoop-folder__flap"
            viewBox="0 0 400 250"
            fill="none"
            aria-hidden="true"
          >
            <path
              d={flapPath}
              transform="translate(0 6)"
              fill="#1d1b1b"
              stroke="#1d1b1b"
              strokeWidth="3.5"
              strokeLinejoin="round"
            />
            <path
              className="duoop-folder__flap-face"
              d={flapPath}
              fill="#ffffff"
              stroke="#1d1b1b"
              strokeWidth="3.5"
              strokeLinejoin="round"
            />
            <path
              d="M42 24Q42 35 54 36Q42 37 42 48Q41 37 30 36Q41 35 42 24Z"
              fill="#373434"
            />
            <path
              d="M68 36H99"
              stroke="#373434"
              strokeWidth="3"
              strokeLinecap="round"
            />
          </svg>
          <span className="duoop-folder__caption">
            <strong>{label}</strong>
          </span>
          <span className="duoop-folder__toggle">
            <span>{open ? 'Put away' : 'View files'}</span>
            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              aria-hidden="true"
            >
              <path d="m8 10 4 4 4-4" />
            </svg>
          </span>
        </button>
      </div>
      <div
        id={id}
        className="duoop-folder__documents"
        inert={!open}
        aria-hidden={!open}
        role="group"
        aria-label={`${label} documents`}
        data-many={items.length > 3}
      >
        {items.map((item, index) => (
          <button
            type="button"
            key={item.id}
            disabled={item.disabled}
            className="duoop-folder__document"
            aria-pressed={selected === item.id}
            style={{
              '--offset': (index % 3) - (Math.min(3, items.length) - 1) / 2,
              '--rise':
                items.length === 1
                  ? '-120%'
                  : items.length >= 3 && index % 3 === 1
                    ? '-150%'
                    : '-112%',
            }}
            onClick={() => {
              setSelected(item.id);
              onSelect?.(item);
            }}
          >
            <span className="duoop-folder__document-top">
              <span>{item.type || 'DOC'}</span>
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.8"
                aria-hidden="true"
              >
                {selected === item.id ? (
                  <path d="m5 12 4 4L19 6" />
                ) : (
                  <path d="M6 3h8l4 4v14H6V3Zm8 0v5h4M9 12h6M9 16h4" />
                )}
              </svg>
            </span>
            <strong>{item.title}</strong>
            <span className="duoop-folder__meta">
              {item.description || 'Document'}
            </span>
          </button>
        ))}
        {!items.length && <p className="duoop-folder__empty">No documents yet.</p>}
      </div>
    </div>
  );
}

sources.efc5ad5e92d45576e08e33f867290b4b5ad92914:
.duoop-folder {
  position: relative;
  isolation: isolate;
  container-type: inline-size;
  width: min(100%, 500px);
  aspect-ratio: 1.12;
  color: #373434;
  font-family: var(--duoop-font, 'DM Sans', sans-serif);
}
.duoop-folder__back {
  position: absolute;
  width: 80%;
  height: auto;
  left: 10%;
  bottom: 12px;
  z-index: 0;
}
.duoop-folder__cover {
  position: absolute;
  z-index: 2;
  left: 10%;
  bottom: 12px;
  width: 80%;
  aspect-ratio: 400 / 250;
}
.duoop-folder__front {
  position: relative;
  isolation: isolate;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  text-align: start;
  padding: 16.25% 8.75% 8.75%;
  border: 0;
  background: transparent;
  color: inherit;
  transform-origin: center 94%;
  transform: perspective(220cqw) rotateX(0deg);
  transition: transform 420ms cubic-bezier(0.22, 0.61, 0.36, 1) 80ms;
  cursor: pointer;
}
.duoop-folder__flap {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
  overflow: visible;
}
.duoop-folder__flap-face {
  transition: fill 150ms;
}
.duoop-folder[data-state='preview'] .duoop-folder__front {
  transform: perspective(220cqw) rotateX(-52deg);
  transition-duration: 300ms;
  transition-delay: 0ms;
}
.duoop-folder[data-state='expanded'] .duoop-folder__front {
  transform: perspective(220cqw) rotateX(-62deg);
  transition-duration: 300ms;
  transition-delay: 0ms;
}
.duoop-folder__front:focus-visible .duoop-folder__flap-face {
  stroke-dasharray: 5 3;
}
.duoop-folder__toggle {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.duoop-folder__caption {
  min-width: 0;
}
.duoop-folder__caption strong {
  font-size: clamp(18px, 5.6cqw, 28px);
  font-weight: 800;
  letter-spacing: 0.025em;
  text-transform: uppercase;
  line-height: 1.08;
  overflow-wrap: anywhere;
}
.duoop-folder__toggle {
  align-items: center;
  font-size: 11px;
  flex-shrink: 0;
  width: 48px;
  text-align: center;
  line-height: 1.4;
}
.duoop-folder__toggle svg {
  width: 24px;
  height: 24px;
  transition: transform 240ms;
}
.duoop-folder[data-open='true'] .duoop-folder__toggle svg {
  transform: rotate(180deg);
}
.duoop-folder__documents {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}
.duoop-folder__document {
  position: absolute;
  left: 50%;
  bottom: 14%;
  width: 44%;
  aspect-ratio: 1.6;
  min-height: 92px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding: clamp(9px, 3cqw, 16px);
  text-align: start;
  border: 2px solid #1d1b1b;
  border-radius: 10px;
  background: #fff;
  color: #373434;
  box-shadow: 0 4px 0 #1d1b1b;
  opacity: 0;
  visibility: hidden;
  transform: translate(-50%, 12%) rotate(calc(var(--offset) * 2deg));
  transition:
    transform 360ms cubic-bezier(0.4, 0, 0.2, 1),
    opacity 100ms ease 240ms,
    visibility 0s linear 360ms,
    background-color 150ms,
    box-shadow 150ms;
}
.duoop-folder__document-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
}
.duoop-folder__document-top svg {
  width: 19px;
  height: 19px;
  flex-shrink: 0;
}
.duoop-folder__document strong {
  font-size: clamp(11px, 2.8cqw, 14px);
  font-weight: 750;
  line-height: 1.35;
  overflow-wrap: anywhere;
}
.duoop-folder__meta {
  margin-top: auto;
  font-size: 10px;
  line-height: 1.4;
  color: #686565;
  overflow-wrap: anywhere;
}
.duoop-folder[data-state='preview'] .duoop-folder__document:nth-child(-n + 3) {
  transition-delay: 0ms;
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0) rotate(calc(var(--offset) * 2deg));
}
.duoop-folder[data-open='true'] .duoop-folder__document {
  transition-delay: 0ms;
  pointer-events: auto;
  opacity: 1;
  visibility: visible;
  transform: translate(calc(-50% + var(--offset) * 55%), var(--rise))
    rotate(calc(var(--offset) * 8deg));
}
.duoop-folder[data-open='true'] .duoop-folder__document:hover,
.duoop-folder[data-open='true'] .duoop-folder__document:focus-visible {
  transform: translate(calc(-50% + var(--offset) * 55%), calc(var(--rise) - 8%))
    rotate(0deg);
  z-index: 3;
}
.duoop-folder__document[aria-pressed='true'] {
  background: #f0eeee;
  z-index: 2;
}
.duoop-folder__front:hover .duoop-folder__flap-face {
  fill: #faf9f8;
}
.duoop-folder__document:active {
  box-shadow: 0 1px 0 #1d1b1b;
}
.duoop-folder button:focus-visible {
  outline: none;
  border-style: dashed;
}
.duoop-folder__document:disabled {
  color: #777171;
  background: #f0eeee;
  cursor: not-allowed;
}
.duoop-folder__empty {
  position: absolute;
  top: 16%;
  inset-inline: 0;
  text-align: center;
  font-size: 13px;
  opacity: 0;
  visibility: hidden;
}
.duoop-folder[data-open='true'] .duoop-folder__empty {
  opacity: 1;
  visibility: visible;
}
/* Large collections use a scrollable landscape-card grid above the cover. */
.duoop-folder[data-open='true'] .duoop-folder__documents[data-many='true'] {
  inset: 0 4% 56%;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  overflow-y: auto;
  padding: 8px 4px;
  pointer-events: auto;
}
.duoop-folder[data-open='true']
  .duoop-folder__documents[data-many='true']
  .duoop-folder__document {
  position: relative;
  left: auto;
  bottom: auto;
  width: 100%;
  transform: none;
}
@media (max-width: 480px) {
  .duoop-folder__front {
    gap: 8px;
    padding-inline: 6%;
  }
  .duoop-folder__document {
    gap: 5px;
  }
  .duoop-folder__toggle {
    width: 40px;
    font-size: 10px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .duoop-folder *,
  .duoop-folder *::before {
    transition: none;
  }
}

