.folder-playground {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 36px 24px 24px;
  background: #f0eeee;
  border: 2px solid #1d1b1b;
  border-radius: 10px;
  box-shadow: 0 4px 0 #1d1b1b;
}
.folder-playground__intro {
  text-align: center;
}
.folder-playground__intro h3 {
  margin: 12px 0 8px;
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -0.6px;
}
.folder-playground__intro p {
  font-size: 13px;
  line-height: 1.7;
  color: #717781;
  margin: 0;
}
.folder-playground__status {
  min-height: 36px;
  margin: 16px 0 0;
  font-size: 12px;
  text-align: center;
  color: #686565;
}
.folder-demo {
  width: 100%;
  display: flex;
  justify-content: center;
  padding: 12px 8px;
}
.folder-mini {
  width: 290px;
  height: 210px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.folder-mini .duoop-folder {
  flex-shrink: 0;
  width: 370px;
  transform: scale(0.65);
}
@media (max-width: 480px) {
  .folder-playground {
    padding: 28px 8px 16px;
  }
  .folder-playground__intro h3 {
    font-size: 21px;
  }
}

